def plot_monthly_rgb_clim(da, col_wrap=4, p_low=2, p_high=98, per_month_stretch=False):
    """
    da: DataArray con dims ('band','month','X','Y') y bandas 'B5_NIR','B4_RED','B3_GREEN'
    col_wrap: nº de columnas del panel
    p_low/p_high: percentiles para el stretch [0..100]
    per_month_stretch: False usa percentiles globales por banda; True calcula por mes
    """
    # Dims
    X = 'X' if 'X' in da.dims else 'x'
    Y = 'Y' if 'Y' in da.dims else 'y'

    # Extent + orientación
    x = da[X].values; y = da[Y].values
    extent = (float(x.min()), float(x.max()), float(y.min()), float(y.max()))
    origin = 'lower' if (y.size > 1 and (y[1]-y[0]) > 0) else 'upper'
    fmt_mill = FuncFormatter(lambda v, pos: f"{v/1e6:.3f}")

    # Helper
    def stretch01(a, lo, hi):
        return np.clip((a - lo) / (hi - lo + 1e-6), 0, 1)

    months = list(da['month'].values)  # 1..12
    n = len(months)
    cols = col_wrap
    rows = math.ceil(n/cols)

    # Percentiles globales por banda (para colores consistentes)
    if not per_month_stretch:
        R_all = da.sel(band='B5_NIR').values.reshape(-1)
        G_all = da.sel(band='B4_RED').values.reshape(-1)
        B_all = da.sel(band='B3_GREEN').values.reshape(-1)
        loR, hiR = np.nanpercentile(R_all, [p_low, p_high])
        loG, hiG = np.nanpercentile(G_all, [p_low, p_high])
        loB, hiB = np.nanpercentile(B_all, [p_low, p_high])

    # Nombres de meses abreviados en español
    month_names = {1:'Ene',2:'Feb',3:'Mar',4:'Abr',5:'May',6:'Jun',
                   7:'Jul',8:'Ago',9:'Sep',10:'Oct',11:'Nov',12:'Dic'}

    fig, axes = plt.subplots(rows, cols, figsize=(4.2*cols, 4.2*rows), squeeze=False)
    axes = axes.ravel()

    for i, m in enumerate(months):
        # Extraer bandas y poner (Y,X)
        R = da.sel(band='B5_NIR', month=m).transpose(Y, X).values
        G = da.sel(band='B4_RED',  month=m).transpose(Y, X).values
        B = da.sel(band='B3_GREEN',month=m).transpose(Y, X).values

        # Relleno simple de NaN con la mediana del frame (evita agujeros al escalar)
        R = np.nan_to_num(R, nan=np.nanmedian(R))
        G = np.nan_to_num(G, nan=np.nanmedian(G))
        B = np.nan_to_num(B, nan=np.nanmedian(B))

        # Stretch (global o por mes)
        if per_month_stretch:
            loR, hiR = np.nanpercentile(R, [p_low, p_high])
            loG, hiG = np.nanpercentile(G, [p_low, p_high])
            loB, hiB = np.nanpercentile(B, [p_low, p_high])

        Rv = stretch01(R, loR, hiR)
        Gv = stretch01(G, loG, hiG)
        Bv = stretch01(B, loB, hiB)
        rgb = np.dstack([Rv, Gv, Bv])

        ax = axes[i]
        ax.imshow(rgb, extent=extent, origin=origin, interpolation='nearest', rasterized=True)
        ax.set_title(f"RGB 5-4-3 — {month_names.get(int(m), m)}")
        ax.set_xlabel('X (×10⁶ m)'); ax.set_ylabel('Y (×10⁶ m)')
        ax.xaxis.set_major_formatter(fmt_mill)
        ax.yaxis.set_major_formatter(fmt_mill)
