"""#### Reporte de fechas con imagenes nulas"""

# --- 1) Tomar una banda como DataArray 3D (time, Y, X) ---
def pick_band_3d(obj, band_name='SR_B5'):
    if isinstance(obj, xr.Dataset):
        if band_name in obj:
            da = obj[band_name]
        else:
            # fallback: primera variable
            da = obj[list(obj.data_vars)[0]]
    else:  # DataArray
        if 'band' in obj.dims:
            if band_name in obj['band'].values:
                da = obj.sel(band=band_name)
            else:
                da = obj.isel(band=0)
        else:
            da = obj  # ya es 1 banda
    X = 'X' if 'X' in da.dims else ('x' if 'x' in da.dims else None)
    Y = 'Y' if 'Y' in da.dims else ('y' if 'y' in da.dims else None)
    if X is None or Y is None:
        raise ValueError("No encuentro dims espaciales 'X'/'Y' (o 'x'/'y').")
    return da.transpose('time', Y, X), X, Y

# --- 2) Fracción de NaN por timestamp (mes) ---
def nan_fraction_per_month(obj, band_name='SR_B5'):
    da3, X, Y = pick_band_3d(obj, band_name=band_name)
    # cuenta NaN sobre el espacio
    nan_count = da3.isnull().sum(dim=(Y, X))
    total_px = da3.sizes[Y] * da3.sizes[X]
    frac = (nan_count / total_px).to_series()
    frac.index = pd.to_datetime(frac.index)  # asegurar datetime
    return frac

