"""#### Imputacion de imagenes nulas por mediana mensual"""

def impute_missing_with_month_median_v3(da_m, ds_monthly_med, missing_times):
    """
    Imputa en 'da_m' los timestamps cuyas fechas (mes-año) están en 'missing_times',
    reemplazando por la mediana del mes correspondiente de 'ds_monthly_med'
    (resampleado en 'MS'). Si la mediana del mes es NaN en todo el frame,
    usa climatología mensual (mediana por mes del año sobre toda la serie).
    Devuelve (filled, report_df).
    """
    # --- util: pasar a DataArray para chequeos de NaN por time ---
    def _to_da(obj):
        return obj.to_array() if isinstance(obj, xr.Dataset) else obj

    def _dims_xy(da):
        X = 'X' if 'X' in da.dims else ('x' if 'x' in da.dims else None)
        Y = 'Y' if 'Y' in da.dims else ('y' if 'y' in da.dims else None)
        if X is None or Y is None:
            raise ValueError("No se encontraron dims espaciales 'X'/'Y' (o 'x'/'y').")
        return X, Y

    def _all_nan_by_time(obj):
        da = _to_da(obj)
        X, Y = _dims_xy(da)
        other = [d for d in da.dims if d not in ('time', X, Y)]
        return da.isnull().all(dim=tuple(other + [Y, X]))

    # --- preparar índices temporales ---
    missing_times = pd.to_datetime(pd.Index(missing_times))
    p_missing = pd.PeriodIndex(missing_times, freq='M')

    t_da = pd.to_datetime(da_m['time'].values)
    p_da = pd.PeriodIndex(t_da, freq='M')

    # marcar qué tiempos de da_m hay que imputar (por mes-año)
    mask_time_bool = np.isin(p_da, p_missing)
    if not mask_time_bool.any():
        return da_m, pd.DataFrame(columns=['imputed'])

    mask_time = xr.DataArray(mask_time_bool, dims=['time'], coords={'time': da_m['time']})

    # --- seleccionar mediana mensual alineada al inicio de mes de cada time ---
    month_starts = p_da.to_timestamp()  # 'start' del período mensual (equiv. a how='start')
    med_sel = ds_monthly_med.sel(time=month_starts)
    med_aligned = med_sel.assign_coords(time=da_m['time'])  # misma long. y coord 'time' que da_m

    # --- fallback: climatología mensual (mediana por mes del año) ---
    clim = da_m.groupby('time.month').median('time', skipna=True, keep_attrs=True)
    mo_da = xr.DataArray(p_da.month, dims=['time'], coords={'time': da_m['time']})
    clim_for_time = clim.sel(month=mo_da).drop_vars('month', errors='ignore')
    clim_for_time = clim_for_time.transpose(*da_m.dims)

    # dónde la mediana mensual quedó toda NaN en un timestamp
    med_all_nan = _all_nan_by_time(med_aligned)
    med_fallback = xr.where(med_all_nan, clim_for_time, med_aligned)

    # --- aplicar imputación sólo en los meses marcados ---
    mask_full = mask_time.broadcast_like(da_m)
    filled = xr.where(mask_full, med_fallback, da_m)

    # --- reporte ---
    imputed_times = pd.to_datetime(da_m['time'].values[mask_time_bool])
    report = pd.DataFrame({'imputed': 1}, index=imputed_times)

    return filled, report

