"""# Calculo de NDWI para la coleccion y binarización"""

# ---------- 1) NDWI mensual desde da_m ----------
def compute_ndwi_monthly(da_m, band_g='B3_GREEN', band_nir='B5_NIR'):
    """
    da_m: DataArray ('band','time','Y','X')
    Devuelve NDWI mensual (misma rejilla y coordenadas).
    """
    assert band_g in da_m['band'].values and band_nir in da_m['band'].values, "Faltan bandas"
    G   = da_m.sel(band=band_g)
    NIR = da_m.sel(band=band_nir)
    ndwi = (G - NIR) / xr.where((G + NIR) == 0, np.nan, (G + NIR))
    # si ya es mensual, no hace falta; si fuera diario: ndwi.resample(time='M').mean('time')
    return ndwi

# ---------- 2) Umbral Otsu (para una 2D) ----------
def otsu_threshold(arr, nbins=256, vmin=-1.0, vmax=1.0):
    a = arr[~np.isnan(arr)]
    if a.size == 0:
        return 0.0
    hist, bin_edges = np.histogram(a, bins=nbins, range=(vmin, vmax))
    p = hist.astype(float) / (hist.sum() + 1e-12)
    omega = np.cumsum(p)
    centers = (bin_edges[:-1] + bin_edges[1:]) / 2.0
    mu = np.cumsum(p * centers)
    mu_t = mu[-1]
    sigma_b2 = (mu_t * omega - mu) ** 2 / (omega * (1 - omega) + 1e-12)
    k = int(np.nanargmax(sigma_b2))
    return (bin_edges[k] + bin_edges[k+1]) / 2.0

# ---------- 3) Clasificación binaria ----------
def classify_ndwi(ndwi_m, method='fixed', thr=0.0, nbins=256):
    """
    ndwi_m: DataArray ('time','Y','X')
    method: 'fixed' (umbral fijo) | 'otsu' (umbral adaptativo por mes)
    thr: umbral si method='fixed'
    Devuelve DataArray binario ('time','Y','X'), dtype uint8 (1=agua, 0=no-agua)
    """
    if method == 'fixed':
        water = (ndwi_m >= thr).astype('uint8')
        water.name = 'water'
        return water

    elif method == 'otsu':
        masks = []
        for t in ndwi_m['time'].values:
            nd = ndwi_m.sel(time=t)                      # 2D (Y,X) con coords correctas
            th = otsu_threshold(nd.values, nbins=nbins)  # umbral por mes
            da_mask = xr.DataArray(
                (nd.values >= th).astype('uint8'),
                coords={'Y': nd['Y'], 'X': nd['X']},
                dims=('Y','X'),
                name='water'
            ).expand_dims(time=[t])
            masks.append(da_mask)
        water = xr.concat(masks, dim='time')
        water.name = 'water'
        return water

    else:
        raise ValueError("method debe ser 'fixed' u 'otsu'")

def plot_monthly_panels(da, col_wrap=4, vmin=None, vmax=None, cmap='RdBu_r',
                        label_x='X', label_y='Y', colorbar=True, max_ticks=4):
    import matplotlib.pyplot as plt
    import pandas as pd
    import xarray as xr

    # Asegurar dims
    assert 'time' in da.dims and ('X' in da.dims or 'x' in da.dims) and ('Y' in da.dims or 'y' in da.dims)
    X = 'X' if 'X' in da.dims else 'x'
    Y = 'Y' if 'Y' in da.dims else 'y'

    # Orientación Y
    y_vals = da[Y].values
    yincrease = bool((y_vals[1] - y_vals[0]) > 0)

    # NO pasar 'aspect="equal"' aquí (deja aspect por defecto o numérico)
    g = da.plot.imshow(
        x=X, y=Y,
        col='time', col_wrap=col_wrap,
        yincrease=yincrease,
        vmin=vmin, vmax=vmax, cmap=cmap,
        add_colorbar=colorbar, robust=False,
        size=3  # tamaño de cada panel (numérico)
    )

    # Ajustes por panel
    for ax, t in zip(g.axes.flat, pd.to_datetime(da['time'].values)):
        ax.set_title(t.strftime('%Y-%m'), fontsize=9)
        ax.set_xlabel(label_x)
        ax.set_ylabel(label_y)
        ax.ticklabel_format(style='plain')
        ax.xaxis.set_major_locator(plt.MaxNLocator(max_ticks))
        ax.yaxis.set_major_locator(plt.MaxNLocator(max_ticks))
        ax.set_aspect('equal')  # <-- aquí sí, por panel

    plt.tight_layout()
    return g

