def plot_panels_time_subset(
    da, *,
    start_year=None, end_year=None,
    n_per_year=None,          # p.ej., 3 (None = todas)
    method='even',            # 'even' | 'first' | 'last'
    months=None,              # lista opcional de meses [1..12] para filtrar
    col_wrap=4,
    vmin=None, vmax=None, cmap='RdBu_r',
    label_x='X', label_y='Y',
    colorbar=True, max_ticks=4,
    coarsen=1, dtype=np.float32
):
    """
    Plotea un DataArray (time,Y,X) o (time,X,Y) seleccionando años y
    un número de imágenes por año.
    """
    assert 'time' in da.dims, "Se requiere dimensión 'time'"
    X = 'X' if 'X' in da.dims else 'x'
    Y = 'Y' if 'Y' in da.dims else 'y'

    # --- recorte por años ---
    if start_year is not None or end_year is not None:
        sy = int(start_year) if start_year is not None else int(pd.to_datetime(da.time.values[0]).year)
        ey = int(end_year)   if end_year   is not None else int(pd.to_datetime(da.time.values[-1]).year)
        da = da.sel(time=slice(f'{sy}-01-01', f'{ey}-12-31'))

    # --- filtrar por meses específicos (si se pide) ---
    if months is not None:
        months = set(int(m) for m in months)
        da = da.sel(time=[t for t in da.time.values if pd.to_datetime(t).month in months])

    # --- agrupar por año y muestrear n_per_year ---
    tindex = pd.to_datetime(da.time.values)
    years = sorted(set(tindex.year))
    times_sel = []
    for y in years:
        idx_y = np.where(tindex.year == y)[0]
        if idx_y.size == 0:
            continue
        if n_per_year is None or n_per_year >= idx_y.size:
            pick = idx_y
        else:
            if method == 'first':
                pick = idx_y[:n_per_year]
            elif method == 'last':
                pick = idx_y[-n_per_year:]
            else:  # 'even'
                pick_pos = np.linspace(0, idx_y.size-1, n_per_year).astype(int)
                pick = idx_y[pick_pos]
        times_sel.extend(da.time.values[pick])

    if len(times_sel) == 0:
        raise ValueError("No hay tiempos tras el filtrado (años/meses/n_per_year).")

    # ordenar cronológicamente
    times_sel = sorted(list(times_sel))
    da = da.sel(time=times_sel)

    # --- coarsen opcional para acelerar ---
    if coarsen and coarsen > 1:
        da = da.coarsen({Y: coarsen, X: coarsen}, boundary='trim').mean()

    # --- orientación/extent ---
    xv = da[X].values; yv = da[Y].values
    extent = (float(xv.min()), float(xv.max()), float(yv.min()), float(yv.max()))
    origin = 'lower' if (yv.size > 1 and (yv[1]-yv[0]) > 0) else 'upper'
    fmt_mill = FuncFormatter(lambda v, pos: f"{v/1e6:.3f}")

    # --- datos en memoria (un único compute) ---
    dat = da.transpose('time', Y, X).astype(dtype).values  # (T,H,W)
    times = pd.to_datetime(da.time.values)
    T = len(times)

    # --- vmin/vmax globales (si no vienen) ---
    if vmin is None or vmax is None:
        flat = dat.reshape(T, -1)
        p2, p98 = np.nanpercentile(flat, [2, 98])
        if vmin is None: vmin = p2
        if vmax is None: vmax = p98
    norm = Normalize(vmin=vmin, vmax=vmax)

    # --- figure ---
    cols = col_wrap
    rows = math.ceil(T/cols)
    fig, axes = plt.subplots(rows, cols, figsize=(4.2*cols, 4.2*rows), squeeze=False)
    axes = axes.ravel()

    im = None
    for i in range(T):
        ax = axes[i]
        im = ax.imshow(dat[i], cmap=cmap, norm=norm, extent=extent,
                       origin=origin, interpolation='nearest', rasterized=True)
        ax.set_title(times[i].strftime('%Y-%m'), fontsize=9)
        ax.set_xlabel(label_x); ax.set_ylabel(label_y)
        ax.xaxis.set_major_locator(MaxNLocator(max_ticks))
        ax.yaxis.set_major_locator(MaxNLocator(max_ticks))
        ax.tick_params(axis='x', labelrotation=45)
        ax.set_aspect('equal')

    for j in range(T, len(axes)):
        axes[j].axis('off')

    if colorbar and im is not None:
        cbar = fig.colorbar(im, ax=[ax for ax in axes[:T]], fraction=0.03, pad=0.02)
        cbar.ax.set_ylabel('valor')

    plt.tight_layout()
    return fig

