def plot_rgb_student_pairs(a_m_sync, student_da, col_wrap=2, title_fmt='%Y-%m'):
    import numpy as np, pandas as pd, matplotlib.pyplot as plt

    # --- helpers mínimos ---
    def _xy_dims(da):
        X = 'X' if 'X' in da.dims else ('x' if 'x' in da.dims else None)
        Y = 'Y' if 'Y' in da.dims else ('y' if 'y' in da.dims else None)
        if X is None or Y is None:
            raise ValueError("No encuentro dims X/Y.")
        return X, Y

    def _increasing(coord):
        arr = coord.values if hasattr(coord, 'values') else np.asarray(coord)
        if arr.size < 2:
            return True
        return bool((arr[1] - arr[0]) > 0)

    # --- dims y orientación de referencia (a_m_sync) y student ---
    Xr, Yr = _xy_dims(a_m_sync)
    Xs, Ys = _xy_dims(student_da)

    ref_x_inc = _increasing(a_m_sync[Xr])
    ref_y_inc = _increasing(a_m_sync[Yr])
    stu_x_inc = _increasing(student_da[Xs])
    stu_y_inc = _increasing(student_da[Ys])

    # flips a aplicar al student para igualar a la referencia
    flip_y = (stu_y_inc != ref_y_inc)
    flip_x = (stu_x_inc != ref_x_inc)

    # Para mostrar ambos con el mismo "north-up"
    origin = 'lower' if ref_y_inc else 'upper'

    # --- bandas 5-4-3 ---
    def _band_dim_and_names_543(da):
        for d in ['band','band_name','channel']:
            if d in da.dims:
                bdim = d
                names = [str(v) for v in da[bdim].values]
                if {'B5_NIR','B4_RED','B3_GREEN'}.issubset(names): return bdim,'B5_NIR','B4_RED','B3_GREEN'
                if {'SR_B5','SR_B4','SR_B3'}.issubset(names):       return bdim,'SR_B5','SR_B4','SR_B3'
                n5 = next((n for n in names if 'B5' in n.upper()), None)
                n4 = next((n for n in names if 'B4' in n.upper()), None)
                n3 = next((n for n in names if 'B3' in n.upper()), None)
                if all([n5,n4,n3]): return bdim,n5,n4,n3
        raise ValueError("No encuentro bandas 5/4/3.")
    bdim, n5, n4, n3 = _band_dim_and_names_543(a_m_sync)

    times = list(pd.to_datetime(student_da['time'].values))
    T = len(times)
    cols = 2
    rows = T
    fig = plt.figure(figsize=(10, 4*rows))

    for i, t in enumerate(times):
        # --- RGB de referencia (a_m_sync) ---
        R = a_m_sync.sel(time=t, **{bdim:n5}).transpose(Yr, Xr).values
        G = a_m_sync.sel(time=t, **{bdim:n4}).transpose(Yr, Xr).values
        B = a_m_sync.sel(time=t, **{bdim:n3}).transpose(Yr, Xr).values
        rgb = np.clip(np.dstack([np.nan_to_num(R,0), np.nan_to_num(G,0), np.nan_to_num(B,0)]), 0, 1)

        ax1 = fig.add_subplot(rows, cols, 2*i+1)
        ax1.imshow(rgb, origin=origin)  # usa el mismo origen que la referencia
        ax1.set_title(f"RGB 5-4-3 — {pd.to_datetime(t).strftime(title_fmt)}")
        ax1.axis('off')

        # --- Student (corrige orientación para matchear a_m_sync) ---
        S = student_da.sel(time=t).transpose(Ys, Xs).values
        if flip_y: S = S[::-1, :]
        if flip_x: S = S[:, ::-1]

        ax2 = fig.add_subplot(rows, cols, 2*i+2)
        ax2.imshow(S, vmin=0, vmax=1, cmap='gray', origin=origin)
        ax2.set_title("Student")
        ax2.axis('off')

    plt.tight_layout(); plt.show()

# Uso:
plot_rgb_student_pairs(a_m_sync, student_all[1:12], title_fmt='%Y-%m')

"""## Calculo de superficie con U-Net"""

# ---------------------------
# Helpers de dims/orientación
# ---------------------------
def _xy_dims(da):
    X = 'X' if 'X' in da.dims else ('x' if 'x' in da.dims else None)
    Y = 'Y' if 'Y' in da.dims else ('y' if 'y' in da.dims else None)
    if X is None or Y is None:
        raise ValueError("No encuentro dims X/Y.")
    return X, Y

def _increasing(coord):
    arr = coord.values if hasattr(coord, 'values') else np.asarray(coord)
    if arr.size < 2:
        return True
    return bool((arr[1] - arr[0]) > 0)

def orient_to_ref(student_da: xr.DataArray, ref_da: xr.DataArray) -> xr.DataArray:
    """Ajusta solo flips en X/Y para que student tenga la misma orientación que ref."""
    Xs, Ys = _xy_dims(student_da)
    Xr, Yr = _xy_dims(ref_da)
    ref_x_inc = _increasing(ref_da[Xr]); ref_y_inc = _increasing(ref_da[Yr])
    stu_x_inc = _increasing(student_da[Xs]); stu_y_inc = _increasing(student_da[Ys])
    out = student_da
    if stu_y_inc != ref_y_inc:
        out = out.isel({Ys: slice(None, None, -1)})
    if stu_x_inc != ref_x_inc:
        out = out.isel({Xs: slice(None, None, -1)})
    return out

def resize_to_ref_grid(student_da: xr.DataArray, ref_da: xr.DataArray) -> xr.DataArray:
    """Redimensiona cada máscara al tamaño espacial de ref (nearest), y copia coords X/Y de ref."""
    Xr, Yr = _xy_dims(ref_da)
    H, W = ref_da.sizes[Yr], ref_da.sizes[Xr]
    times = list(pd.to_datetime(student_da['time'].values))
    Ys, Xs = _xy_dims(student_da)

    outs = []
    for t in times:
        m = student_da.sel(time=t).transpose(Ys, Xs).values.astype(np.uint8)
        if m.shape != (H, W):
            m = resize(m, (H, W), order=0, preserve_range=True, anti_aliasing=False).astype(np.uint8)
        da = xr.DataArray(m, coords={Yr: ref_da[Yr], Xr: ref_da[Xr]}, dims=(Yr, Xr))
        da = da.expand_dims(time=[t])
        outs.append(da)
    return xr.concat(outs, dim='time').assign_coords(time=times).rename('student_geo')

# ---------------------------
# Cálculo de área por mes
# ---------------------------
def _looks_geographic(X, Y):
    # heurística simple para lon/lat en grados
    xmin, xmax = float(np.nanmin(X)), float(np.nanmax(X))
    ymin, ymax = float(np.nanmin(Y)), float(np.nanmax(Y))
    return (-360 <= xmin <= 360) and (-360 <= xmax <= 360) and (-90 <= ymin <= 90) and (-90 <= ymax <= 90)

def area_ts_from_mask(student_geo: xr.DataArray) -> pd.DataFrame:
    """
    Calcula área de agua por fecha.
    - Si coords están en grados lon/lat: usa aproximación esférica con R=6371008.8 m.
    - Si coords parecen proyectadas (m): usa |dx|*|dy| por píxel.
    Retorna DataFrame con columnas: time, area_m2, area_km2.
    """
    X, Y = _xy_dims(student_geo)
    times = list(pd.to_datetime(student_geo['time'].values))
    lon_or_x = np.asarray(student_geo[X].values, dtype=float)
    lat_or_y = np.asarray(student_geo[Y].values, dtype=float)

    if _looks_geographic(lon_or_x, lat_or_y):
        # ---- área geodésica aproximada desde lon/lat en grados ----
        def _edges(c):
            e = np.empty(c.size+1, dtype=float)
            e[1:-1] = 0.5*(c[:-1] + c[1:])
            step = (c[1]-c[0]) if c.size>=2 else 1.0
            e[0]  = c[0] - 0.5*step
            e[-1] = c[-1] + 0.5*step
            return e
        lon_e = _edges(lon_or_x)  # (W+1,)
        lat_e = _edges(lat_or_y)  # (H+1,)

        R = 6371008.8
        dlam = np.radians(np.diff(lon_e))           # (W,)
        dphi = np.radians(np.diff(lat_e))           # (H,)
        lat_c = (lat_e[:-1] + lat_e[1:]) / 2.0      # (H,)
        # Área celda ~ R^2 * cos(phi_c) * dphi * dlam
        cell_area = (R**2) * np.outer(dphi * np.cos(np.radians(lat_c)), dlam)  # (H,W)

        areas = []
        for t in times:
            m = student_geo.sel(time=t).transpose(Y, X).values.astype(np.uint8)
            areas.append(float(np.nansum(m * cell_area)))
        df = pd.DataFrame({'time': times, 'area_m2': areas})
    else:
        # ---- área en CRS métrico (dx*dy) ----
        # dx, dy a partir de diferencias medias (por si el sampling no es exactamente constante)
        dx = np.nanmedian(np.diff(lon_or_x))   # puede ser negativo → usar abs
        dy = np.nanmedian(np.diff(lat_or_y))
        pix_area = abs(dx * dy)                # m² por píxel
        areas = []
        for t in times:
            m = student_geo.sel(time=t).values.astype(np.uint8)
            areas.append(float(np.nansum(m)) * pix_area)
        df = pd.DataFrame({'time': times, 'area_m2': areas})

    df['area_km2'] = df['area_m2'] / 1e6
    return df.sort_values('time').reset_index(drop=True)

