def _to_df_ref(area_series):
    """Normaliza area_series a DataFrame con columnas ['time','water_km2']."""
    if isinstance(area_series, pd.Series):
        df = area_series.to_frame(name='water_km2').reset_index()
        # intenta nombrar columna temporal
        if 'index' in df.columns:
            df = df.rename(columns={'index':'time'})
        elif df.columns[0] != 'time':
            df = df.rename(columns={df.columns[0]: 'time'})
    elif isinstance(area_series, pd.DataFrame):
        df = area_series.copy()
        if 'time' not in df.columns:
            if isinstance(df.index, pd.DatetimeIndex):
                df = df.reset_index().rename(columns={'index':'time'})
            else:
                raise ValueError("En area_series no encuentro columna/índice temporal.")
        if 'water_km2' not in df.columns:
            # toma la primera numérica si no está ese nombre
            num_cols = df.select_dtypes(include=[np.number]).columns
            if len(num_cols) == 0:
                raise ValueError("area_series no tiene columna numérica.")
            df = df[['time', num_cols[0]]].rename(columns={num_cols[0]:'water_km2'})
        else:
            df = df[['time','water_km2']]
    else:
        raise TypeError("area_series debe ser pandas Series o DataFrame.")
    df['time'] = pd.to_datetime(df['time'])
    return df.sort_values('time')

# 1) Normalizar ambas
