# ---------------- helpers ----------------
def _xy_dims(da):
    X = 'X' if 'X' in da.dims else ('x' if 'x' in da.dims else None)
    Y = 'Y' if 'Y' in da.dims else ('y' if 'y' in da.dims else None)
    if X is None or Y is None: raise ValueError("No encuentro dims espaciales X/Y (o x/y).")
    return X, Y

def _to_datetime(times):
    return pd.to_datetime(np.asarray(times))

def _pick_rgb_bands(ds_or_da):
    """Devuelve dict {'R':DA_B5,'G':DA_B4,'B':DA_B3} con dims (time,Y,X)."""
    if isinstance(ds_or_da, xr.Dataset):
        # nombres más comunes
        cand = {
            'R': ['B5_NIR','SR_B5'],
            'G': ['B4_RED','SR_B4'],
            'B': ['B3_GREEN','SR_B3'],
        }
        out = {}
        for k, names in cand.items():
            for nm in names:
                if nm in ds_or_da.data_vars:
                    out[k] = ds_or_da[nm]
                    break
            if k not in out:
                raise KeyError(f"No encuentro banda para {k} (intenté {names}).")
    else:
        # DataArray multibanda
        if 'band' not in ds_or_da.dims:
            raise ValueError("Se esperaba 'band' en DataArray para RGB.")
        def sel_first(cands):
            for nm in cands:
                if nm in ds_or_da['band'].values: return ds_or_da.sel(band=nm)
            raise KeyError(f"No encuentro ninguna de {cands} en 'band'.")
        out = {
            'R': sel_first(['B5_NIR','SR_B5']),
            'G': sel_first(['B4_RED','SR_B4']),
            'B': sel_first(['B3_GREEN','SR_B3']),
        }
    # homogeneizar dims
    for k in ['R','G','B']:
        X, Y = _xy_dims(out[k])
        out[k] = out[k].transpose('time', Y, X)
    return out

def _get_ndwi(da_ndwi, rgb=None):
    """Si da_ndwi es None o no tiene NDWI, lo calcula como (G-NIR)/(G+NIR) a partir de rgb dict."""
    if da_ndwi is not None:
        # Dataset o DataArray
        if isinstance(da_ndwi, xr.Dataset):
            for nm in ['NDWI','ndwi']:
                if nm in da_ndwi.data_vars:
                    return da_ndwi[nm]
            raise KeyError("El Dataset NDWI no contiene 'NDWI'/'ndwi'.")
        else:
            return da_ndwi  # ya es DataArray
    # calcular desde RGB (NIR=B5, GREEN=B3)
    if rgb is None: raise ValueError("Para calcular NDWI necesito 'rgb'.")
    num = rgb['B'] - rgb['R']   # G - NIR
    den = rgb['B'] + rgb['R']   # G + NIR
    ndwi = (num / xr.where(den==0, np.nan, den)).rename('NDWI')
    return ndwi

def _stretch01(a, lo, hi):
    return np.clip((a - lo) / (hi - lo + 1e-6), 0, 1)

# ---------------- función principal ----------------
def plot_random_triplets(a_m_sync, student_all, ndwi_da=None, k=6, seed=0,
                         col_wrap=3, thr=0.5, rgb_p=(2,98), per_panel_stretch=False):
    """
    a_m_sync : Dataset/DataArray con bandas ópticas (B5_NIR|SR_B5, B4_RED|SR_B4, B3_GREEN|SR_B3)
    student_all : DataArray (time,Y,X) prob o binaria
    ndwi_da : Dataset/DataArray con NDWI; si None, se calcula desde a_m_sync
    k : nº de fechas al azar (sin reemplazo)
    thr : umbral para binarizar student (clasificación)
    rgb_p : percentiles (low, high) para stretch RGB
    per_panel_stretch : False = stretch global sobre las k fechas; True = por panel
    """
    # --- tiempos comunes ---
    t_rgb = _to_datetime(a_m_sync['time'].values)
    t_stu = _to_datetime(student_all['time'].values)
    common = np.intersect1d(t_rgb.values, t_stu.values)
    if ndwi_da is not None:
        t_ndw = _to_datetime(ndwi_da['time'].values)
        common = np.intersect1d(common, t_ndw.values)
    if common.size == 0:
        raise ValueError("No hay tiempos en común entre RGB, Student (y NDWI).")

    rng = np.random.default_rng(seed)
    pick = rng.choice(common, size=min(k, common.size), replace=False)
    pick = np.sort(pick)  # para que queden ordenados

    # --- preparar RGB y NDWI ---
    rgb = _pick_rgb_bands(a_m_sync)  # {'R','G','B'} en dims (time,Y,X)
    # crear versión filtrada por tiempos
    sel = dict(time=pick)
    R = rgb['R'].sel(**sel); G = rgb['G'].sel(**sel); B = rgb['B'].sel(**sel)
    # NDWI
    ndwi_full = _get_ndwi(ndwi_da, rgb={'R':R, 'B':B})  # usa R=B5 (NIR) y B=B3 (GREEN)
    ndwi = ndwi_full.sel(**sel)

    # Student
    stu = student_all.sel(time=pick)

    # --- extent / orientation (asumimos misma grilla para los tres) ---
    X, Y = _xy_dims(R)
    xv, yv = R[X].values, R[Y].values
    extent = (float(xv.min()), float(xv.max()), float(yv.min()), float(yv.max()))
    origin = 'lower' if (yv.size>1 and (yv[1]-yv[0])>0) else 'upper'
    fmt_mill = FuncFormatter(lambda v, pos: f"{v/1e6:.3f}")

    # --- percentiles globales para RGB (sobre las k fechas) ---
    if not per_panel_stretch:
        Rall = R.values.reshape(-1); Gall = G.values.reshape(-1); Ball = B.values.reshape(-1)
        loR, hiR = np.nanpercentile(Rall, rgb_p); loG, hiG = np.nanpercentile(Gall, rgb_p); loB, hiB = np.nanpercentile(Ball, rgb_p)

    # --- figura: 3 columnas por tiempo (RGB | NDWI | Student) ---
    T = pick.size
    cols = 3
    rows = math.ceil(T / col_wrap) if col_wrap>0 else T
    fig = plt.figure(figsize=(4.2*cols*min(col_wrap,T), 4.2*rows))

    for i, t in enumerate(pick):
        # extraer arrays (Y,X)
        Rt = R.sel(time=t).transpose(Y, X).values
        Gt = G.sel(time=t).transpose(Y, X).values
        Bt = B.sel(time=t).transpose(Y, X).values
        Nt = ndwi.sel(time=t).transpose(Y, X).values
        St = stu.sel(time=t).transpose(Y, X).values

        # NaN-safe para stretch
        Rt = np.nan_to_num(Rt, nan=np.nanmedian(Rt))
        Gt = np.nan_to_num(Gt, nan=np.nanmedian(Gt))
        Bt = np.nan_to_num(Bt, nan=np.nanmedian(Bt))

        if per_panel_stretch:
            loR, hiR = np.nanpercentile(Rt, rgb_p)
            loG, hiG = np.nanpercentile(Gt, rgb_p)
            loB, hiB = np.nanpercentile(Bt, rgb_p)
        rgb_img = np.dstack([_stretch01(Rt,loR,hiR), _stretch01(Gt,loG,hiG), _stretch01(Bt,loB,hiB)])

        # --- paneles: RGB ---
        ax1 = fig.add_subplot(rows, col_wrap*cols, i*cols + 1)
        ax1.imshow(rgb_img, extent=extent, origin=origin, interpolation='nearest', rasterized=True)
        ax1.set_title(f"RGB 5-4-3 — {pd.to_datetime(t).strftime('%Y-%m')}")
        ax1.set_xlabel('X (×10⁶ m)'); ax1.set_ylabel('Y (×10⁶ m)')
        ax1.xaxis.set_major_formatter(fmt_mill); ax1.yaxis.set_major_formatter(fmt_mill)
        ax1.tick_params(axis='x', labelrotation=45); ax1.set_aspect('equal')

        # --- NDWI ---
        ax2 = fig.add_subplot(rows, col_wrap*cols, i*cols + 2)
        im2 = ax2.imshow(Nt, extent=extent, origin=origin, vmin=-0.6, vmax=0.6, cmap='RdBu_r', interpolation='nearest', rasterized=True)
        ax2.set_title("NDWI"); ax2.set_xlabel('X (×10⁶ m)'); ax2.set_ylabel(''); ax2.yaxis.set_ticklabels([])
        ax2.xaxis.set_major_formatter(fmt_mill); ax2.tick_params(axis='x', labelrotation=45); ax2.set_aspect('equal')
        cbar2 = plt.colorbar(im2, ax=ax2, fraction=0.046, pad=0.02); cbar2.ax.set_ylabel('NDWI')

        # --- Student (binaria con umbral) ---
        ax3 = fig.add_subplot(rows, col_wrap*cols, i*cols + 3)
        if np.issubdtype(stu.dtype, np.floating):
            Stb = (St >= thr).astype(float)
        else:
            Stb = (St > 0).astype(float)
        im3 = ax3.imshow(Stb, extent=extent, origin=origin, vmin=0, vmax=1, cmap='gray', interpolation='nearest', rasterized=True)
        ax3.set_title(f"Student (thr={thr})"); ax3.set_xlabel('X (×10⁶ m)'); ax3.set_ylabel(''); ax3.yaxis.set_ticklabels([])
        ax3.xaxis.set_major_formatter(fmt_mill); ax3.tick_params(axis='x', labelrotation=45); ax3.set_aspect('equal')
        cbar3 = plt.colorbar(im3, ax=ax3, fraction=0.046, pad=0.02); cbar3.ax.set_ylabel('agua (0/1)')

    plt.tight_layout()
    plt.show()

a_m_sync

