def plot_percentile_triplets(
    a_m_sync,
    student_all,
    ndwi_da=None,
    percentiles_info=None,
    col_wrap=3,
    thr=0.5,
    rgb_p=(2, 98),
    per_panel_stretch=False,
):
    """
    Plotea tripletes (RGB, NDWI, Student) para fechas asociadas a percentiles.

    Parámetros
    ----------
    a_m_sync : xr.Dataset/xr.DataArray
        Dataset/DataArray con bandas ópticas (B5_NIR|SR_B5, B4_RED|SR_B4, B3_GREEN|SR_B3).
    student_all : xr.DataArray
        DataArray (time, Y, X) con probabilidad o clasificación binaria del modelo (Student).
    ndwi_da : xr.Dataset/xr.DataArray, opcional
        NDWI precomputado. Si es None, se calcula a partir de a_m_sync.
    percentiles_info : lista
        Lista de tuplas (label, fecha_str) o (label, pd.Timestamp).
        Ejemplo:
        [
            ("P10", "2016-01-31"),
            ("P25", "2011-01-31"),
            ...
        ]
        La función buscará, para cada fecha objetivo, el tiempo más cercano
        disponible en las series RGB/NDWI/Student.
    col_wrap : int
        Número de tripletes por fila.
    thr : float
        Umbral para binarizar la salida de student_all si es flotante.
    rgb_p : tuple
        Percentiles (low, high) para el stretch de RGB.
    per_panel_stretch : bool
        Si False: stretch global sobre todas las fechas seleccionadas.
        Si True: stretch independiente por panel.
    """

    if percentiles_info is None or len(percentiles_info) == 0:
        raise ValueError("Debes pasar 'percentiles_info' con (label, fecha).")

    # --- tiempos comunes disponibles ---
    t_rgb = _to_datetime(a_m_sync["time"].values)
    t_stu = _to_datetime(student_all["time"].values)
    common = np.intersect1d(t_rgb.values, t_stu.values)

    if ndwi_da is not None:
        t_ndw = _to_datetime(ndwi_da["time"].values)
        common = np.intersect1d(common, t_ndw.values)

    if common.size == 0:
        raise ValueError("No hay tiempos en común entre RGB, Student (y NDWI).")

    # Convertir common a pandas.DatetimeIndex para facilitar búsqueda por cercanía
    common_dt = pd.to_datetime(common)

    # Procesar percentiles_info: (label, target_date)
    labels = []
    pick = []
    for label, fecha in percentiles_info:
        labels.append(label)
        target = pd.to_datetime(fecha)

        # índice de la fecha disponible más cercana al target
        idx = np.argmin(np.abs(common_dt - target))
        pick.append(common_dt[idx])

    # Asegurar orden cronológico (y reordenar labels en el mismo orden)
    pick = pd.to_datetime(pick)
    order = np.argsort(pick.values)
    pick = pick.values[order]
    labels = [labels[i] for i in order]

    # --- preparar RGB y NDWI ---
    rgb = _pick_rgb_bands(a_m_sync)  # {'R','G','B'} en dims (time,Y,X)
    sel = dict(time=pick)
    R = rgb["R"].sel(**sel)
    G = rgb["G"].sel(**sel)
    B = rgb["B"].sel(**sel)

    # NDWI
    ndwi_full = _get_ndwi(ndwi_da, rgb={"R": R, "B": B})  # usa R=B5 (NIR) y B=B3 (GREEN)
    ndwi = ndwi_full.sel(**sel)

    # Student
    stu = student_all.sel(time=pick)

    # --- extent / orientation ---
    X, Y = _xy_dims(R)
    xv, yv = R[X].values, R[Y].values
    extent = (float(xv.min()), float(xv.max()), float(yv.min()), float(yv.max()))
    origin = "lower" if (yv.size > 1 and (yv[1] - yv[0]) > 0) else "upper"
    fmt_mill = FuncFormatter(lambda v, pos: f"{v/1e6:.3f}")

    # --- percentiles globales para RGB (sobre todas las fechas seleccionadas) ---
    if not per_panel_stretch:
        Rall = R.values.reshape(-1)
        Gall = G.values.reshape(-1)
        Ball = B.values.reshape(-1)
        loR, hiR = np.nanpercentile(Rall, rgb_p)
        loG, hiG = np.nanpercentile(Gall, rgb_p)
        loB, hiB = np.nanpercentile(Ball, rgb_p)

    # --- figura: 3 columnas por tiempo (RGB | NDWI | Student) ---
    T = len(pick)
    cols = 3
    rows = math.ceil(T / col_wrap) if col_wrap > 0 else T

    fig = plt.figure(figsize=(4.2 * cols * min(col_wrap, T), 4.2 * rows))

    for i, t in enumerate(pick):
        # extraer arrays (Y,X)
        Rt = R.sel(time=t).transpose(Y, X).values
        Gt = G.sel(time=t).transpose(Y, X).values
        Bt = B.sel(time=t).transpose(Y, X).values
        Nt = ndwi.sel(time=t).transpose(Y, X).values
        St = stu.sel(time=t).transpose(Y, X).values

        # NaN-safe para stretch
        Rt = np.nan_to_num(Rt, nan=np.nanmedian(Rt))
        Gt = np.nan_to_num(Gt, nan=np.nanmedian(Gt))
        Bt = np.nan_to_num(Bt, nan=np.nanmedian(Bt))

        # Stretch por panel (opcional)
        if per_panel_stretch:
            loR, hiR = np.nanpercentile(Rt, rgb_p)
            loG, hiG = np.nanpercentile(Gt, rgb_p)
            loB, hiB = np.nanpercentile(Bt, rgb_p)

        rgb_img = np.dstack([
            _stretch01(Rt, loR, hiR),
            _stretch01(Gt, loG, hiG),
            _stretch01(Bt, loB, hiB),
        ])

        # Texto para la fecha y el label del percentil
        t_str = pd.to_datetime(t).strftime("%Y-%m-%d")
        label = labels[i] if i < len(labels) else ""

        # --- panel RGB ---
        ax1 = fig.add_subplot(rows, col_wrap * cols, i * cols + 1)
        ax1.imshow(
            rgb_img,
            extent=extent,
            origin=origin,
            interpolation="nearest",
            rasterized=True,
        )
        ax1.set_title(f"RGB 5-4-3 — {t_str} ({label})")
        ax1.set_xlabel("X (×10⁶ m)")
        ax1.set_ylabel("Y (×10⁶ m)")
        ax1.xaxis.set_major_formatter(fmt_mill)
        ax1.yaxis.set_major_formatter(fmt_mill)
        ax1.tick_params(axis="x", labelrotation=45)
        ax1.set_aspect("equal")

        # --- NDWI ---
        ax2 = fig.add_subplot(rows, col_wrap * cols, i * cols + 2)
        im2 = ax2.imshow(
            Nt,
            extent=extent,
            origin=origin,
            vmin=-0.6,
            vmax=0.6,
            cmap="RdBu_r",
            interpolation="nearest",
            rasterized=True,
        )
        ax2.set_title("NDWI")
        ax2.set_xlabel("X (×10⁶ m)")
        ax2.set_ylabel("")
        ax2.yaxis.set_ticklabels([])
        ax2.xaxis.set_major_formatter(fmt_mill)
        ax2.tick_params(axis="x", labelrotation=45)
        ax2.set_aspect("equal")
        cbar2 = plt.colorbar(im2, ax=ax2, fraction=0.046, pad=0.02)
        cbar2.ax.set_ylabel("NDWI")

        # --- Student (binaria) ---
        ax3 = fig.add_subplot(rows, col_wrap * cols, i * cols + 3)
        if np.issubdtype(stu.dtype, np.floating):
            Stb = (St >= thr).astype(float)
        else:
            Stb = (St > 0).astype(float)
        im3 = ax3.imshow(
            Stb,
            extent=extent,
            origin=origin,
            vmin=0,
            vmax=1,
            cmap="gray",
            interpolation="nearest",
            rasterized=True,
        )
        ax3.set_title(f"Student (thr={thr})")
        ax3.set_xlabel("X (×10⁶ m)")
        ax3.set_ylabel("")
        ax3.yaxis.set_ticklabels([])
        ax3.xaxis.set_major_formatter(fmt_mill)
        ax3.tick_params(axis="x", labelrotation=45)
        ax3.set_aspect("equal")
        cbar3 = plt.colorbar(im3, ax=ax3, fraction=0.046, pad=0.02)
        cbar3.ax.set_ylabel("agua (0/1)")

    plt.tight_layout()
    plt.show()

