import numpy as np
import xarray as xr
import matplotlib.pyplot as plt

# ============================================================
# 0. SUPUESTOS
# ============================================================
# - a_m_sync: xr.DataArray ya cargado, con:
#   dims: incluye 'time', 'band' y espaciales ('X','Y' o 'x','y')
#   coords: band = ['B5_NIR','B4_RED','B3_GREEN']
# - Vamos a usar un diccionario de años ya clasificados:
#   RELLENA years_by_class con tus años secos / medios / húmedos.


# ==========> COMPLETAR CON TUS AÑOS <===========
years_by_class = {
    "Seco":  [1984, 1985, 1988, 1992, 2012, 2013, 2014, 2015, 2016],
    "Medio": [1986, 1987, 1990, 1991, 1993, 1994, 1995, 1997, 1998, 2002, 2007, 2010],
    "Húmedo":[1999, 2000, 2001, 2003, 2004, 2005, 2008, 2011, 2018, 2019, 2020, 2021, 2022, 2023],
}
# ==============================================

band_R = "B5_NIR"
band_G = "B4_RED"
band_B = "B3_GREEN"

# ============================================================
# 1. FUNCIONES AUXILIARES
# ============================================================

def stretch_01(arr, p_low=2, p_high=98):
    """
    Escala array a 0–1 usando percentiles (p_low, p_high).
    Maneja NaNs.
    """
    vmin, vmax = np.nanpercentile(arr, [p_low, p_high])
    arr = (arr - vmin) / (vmax - vmin + 1e-9)
    return np.clip(arr, 0, 1)


def median_rgb_for_years(da, years, band_R, band_G, band_B):
    """
    Calcula la imagen mediana (RGB) para un conjunto de años.

    da      : xr.DataArray con dims que incluyen 'time' y 'band'
    years   : lista de int (años)
    band_*  : nombres de bandas en la coord 'band'
    Devuelve: (R_med, G_med, B_med) como np.array 2D
    """
    if len(years) == 0:
        raise ValueError("La lista de años está vacía.")

    # Filtrar por años
    da_class = da.sel(time=da["time"].dt.year.isin(years))

    if da_class.time.size == 0:
        raise ValueError(f"No hay imágenes para los años: {years}")

    # Mediana en el tiempo
    med = da_class.median(dim="time", skipna=True)  # dims: band, Y, X (o similar)

    # Seleccionar bandas por etiqueta en la coord 'band'
    R = med.sel(band=band_R)
    G = med.sel(band=band_G)
    B = med.sel(band=band_B)

    # Detectar nombres de dims espaciales (X/Y o x/y)
    ydim = [d for d in R.dims if d.lower() in ("y", "lat")][0]
    xdim = [d for d in R.dims if d.lower() in ("x", "lon")][0]

    Rv = R.transpose(ydim, xdim).values
    Gv = G.transpose(ydim, xdim).values
    Bv = B.transpose(ydim, xdim).values

    return Rv, Gv, Bv, xdim, ydim, R


# ============================================================
# 2. PLOT: 3 IMÁGENES RGB MEDIANAS (SECO / MEDIO / HÚMEDO)
# ============================================================

def plot_median_rgb_three_classes(da, years_by_class, band_R="B5_NIR", band_G="B4_RED", band_B="B3_GREEN"):
    classes = ["Seco", "Medio", "Húmedo"]

    fig, axes = plt.subplots(1, 3, figsize=(15, 5), constrained_layout=True)

    for ax, cls in zip(axes, classes):
        years = years_by_class.get(cls, [])
        if not years:
            ax.set_title(f"Sin años para clase {cls}")
            ax.axis("off")
            continue

        Rv, Gv, Bv, xdim, ydim, R_da = median_rgb_for_years(da, years, band_R, band_G, band_B)

        # Stretch 0–1 por clase
        Rn = stretch_01(Rv, 2, 98)
        Gn = stretch_01(Gv, 2, 98)
        Bn = stretch_01(Bv, 2, 98)
        rgb = np.dstack([Rn, Gn, Bn])

        # Extent geográfico si hay coords
        if (xdim in R_da.coords) and (ydim in R_da.coords):
            xv = R_da[xdim].values
            yv = R_da[ydim].values
            extent = (float(xv.min()), float(xv.max()),
                      float(yv.min()), float(yv.max()))
            origin = "lower" if (yv[1] - yv[0]) > 0 else "upper"
            ax.imshow(rgb, extent=extent, origin=origin)
        else:
            ax.imshow(rgb)

        ax.set_title(f"Mediana RGB – años {cls}")
        ax.set_xticks([])
        ax.set_yticks([])

    plt.suptitle("", y=0.98)
    plt.show()

# === LLAMADA PRINCIPAL ===
# a_m_sync es tu DataArray (band,time,Y,X)
plot_median_rgb_three_classes(a_m_sync, years_by_class,
                               band_R="B5_NIR", band_G="B4_RED", band_B="B3_GREEN")

import numpy as np
import xarray as xr
import matplotlib.pyplot as plt

# ============================================================
# NDWI MEDIANO POR CLASE (SECO / MEDIO / HÚMEDO)
# ============================================================
# Supuestos:
# - a_m_sync: xr.DataArray con dims (time, band, Y, X) o similar
# - coords: band = ['B5_NIR','B4_RED','B3_GREEN']
# - years_by_class: dict con listas de años por clase
# - Ya definiste antes median_rgb_for_years(), pero aquí NO la usamos:
#   calculamos la mediana directamente y luego el NDWI.

band_NIR   = "B5_NIR"
band_GREEN = "B3_GREEN"

def median_ndwi_for_years(da, years, band_nir="B5_NIR", band_green="B3_GREEN"):
    """
    Calcula NDWI mediano para un conjunto de años.

    da        : xr.DataArray (incluye dims 'time' y 'band')
    years     : lista de int (años)
    band_nir  : nombre de la banda NIR en coord 'band'
    band_green: nombre de la banda GREEN en coord 'band'

    Devuelve: (ndwi_vals, xdim, ydim, ndwi_da)
    """
    if len(years) == 0:
        raise ValueError("La lista de años está vacía.")

    # Filtrar por años
    da_class = da.sel(time=da["time"].dt.year.isin(years))

    if da_class.time.size == 0:
        raise ValueError(f"No hay imágenes para los años: {years}")

    # Mediana en el tiempo
    med = da_class.median(dim="time", skipna=True)   # dims: band, Y, X

    nir   = med.sel(band=band_nir)
    green = med.sel(band=band_green)

    ndwi = (green - nir) / (green + nir + 1e-9)

    # Detectar dims espaciales
    ydim = [d for d in ndwi.dims if d.lower() in ("y", "lat")][0]
    xdim = [d for d in ndwi.dims if d.lower() in ("x", "lon")][0]

    ndwi_vals = ndwi.transpose(ydim, xdim).values

    return ndwi_vals, xdim, ydim, ndwi


def plot_median_ndwi_three_classes(
    da,
    years_by_class,
    band_nir="B5_NIR",
    band_green="B3_GREEN",
    vmin=-0.6,
    vmax=0.6
):
    """
    Plotea NDWI mediano para años secos / medios / húmedos.
    """
    classes = ["Seco", "Medio", "Húmedo"]

    fig, axes = plt.subplots(1, 3, figsize=(15, 5), constrained_layout=True)

    for ax, cls in zip(axes, classes):
        years = years_by_class.get(cls, [])
        if not years:
            ax.set_title(f"Sin años para clase {cls}")
            ax.axis("off")
            continue

        ndwi_vals, xdim, ydim, ndwi_da = median_ndwi_for_years(
            da, years, band_nir=band_nir, band_green=band_green
        )

        # Extent geográfico si hay coords
        if (xdim in ndwi_da.coords) and (ydim in ndwi_da.coords):
            xv = ndwi_da[xdim].values
            yv = ndwi_da[ydim].values
            extent = (float(xv.min()), float(xv.max()),
                      float(yv.min()), float(yv.max()))
            origin = "lower" if (yv[1] - yv[0]) > 0 else "upper"
            im = ax.imshow(
                ndwi_vals,
                extent=extent,
                origin=origin,
                cmap="RdBu_r",
                vmin=vmin,
                vmax=vmax,
            )
        else:
            im = ax.imshow(
                ndwi_vals,
                cmap="RdBu_r",
                vmin=vmin,
                vmax=vmax,
            )

        ax.set_title(f"NDWI mediano – años {cls}")
        ax.set_xticks([])
        ax.set_yticks([])

    cbar = fig.colorbar(im, ax=axes.ravel().tolist(), shrink=0.8)
    cbar.set_label("NDWI")
    plt.suptitle("NDWI mediano por clase de año (Seco–Medio–Húmedo)", y=0.98)
    plt.show()

# === LLAMADA PRINCIPAL ===
