plt.grid(alpha=0.3); plt.legend(); plt.tight_layout(); plt.show()

"""### `forecast_future`:
pronóstico autoregresivo mensual (L→1) con UNet2D

**Idea.**  
Usa las **últimas L máscaras** (`0/1`) como entrada de la red para predecir el mes `t`. Luego **alimenta su propia salida** (autoregresivo) para predecir `t+1`, y así hasta `steps` meses.

**Componentes clave**
- `make_input_stack(frames_L, resize_to)`: apila `[L,H,W] → [1,L,H',W']` (nearest si hay resize para conservar 0/1).
- `monthly_range_after(last_time, n_months)`: genera los timestamps futuros mensuales.
- Buffer `buf`: lista con las **L últimas observaciones** (máscaras) en `[H,W]`.  
  En cada paso: `x = stack(buf) → net(x) → p = sigmoid(logits) → b = (p>=thr)` y **desplaza** `buf` agregando `b`.

**Flujo (`forecast_future`)**
1. `hist = student_all.transpose('time',Y,X).values` → `[T,H,W]` binario.  
   `buf = hist[-L:,...]` (últimos L).
2. Para cada mes futuro:
   - `x = make_input_stack(buf)` → `[1,L,H',W']`.
   - `p = net(x)` con `sigmoid` → probabilidad `[H',W']`.
   - `b = (p>=thr)` → binario.  
   - Si `resize_to` ≠ `(H,W)`, reescala `b` de vuelta a `(H,W)` **solo para el buffer**.
   - Actualiza `buf = buf[1:] + [b_(H,W)]`.
3. Construye dos `DataArray`:
   - `prob_da('prob')`: probabilidades `[steps,H',W']`.
   - `bin_da('bin')`: binario `[steps,H',W']`.  
   Si hay `resize_to`, coords espaciales son índices `[0..H'-1]`, `[0..W'-1]`; si no, hereda `Y/X` originales.

**Parámetros**
- `L`: longitud de ventana (número de frames pasados).
- `steps`: meses a pronosticar.
- `thr`: umbral de binarización (ej. 0.5).
- `resize_to`: tamaño de trabajo de la red (rápido y consistente).
- `device`: CPU/GPU (auto si no se especifica).

**Buenas prácticas / tips**
- **Calibración**: evaluá `thr` (0.3–0.7) según ROC/PR en validación.
- **Suavizado autoregresivo**: en vez de alimentar `b` (duro), podés alimentar **`p`** (prob) al buffer (requiere entrenar la red con entradas en `float`).
- **Teacher Forcing vs Free-running**: durante entrenamiento, podés entrenar con ventanas “reales” y también con ventanas que incluyan predicciones para robustecer el multi-paso (scheduled sampling).
- **Consistencia espacial**: si vas a comparar con GT a full-res, reescala `prob_da/bin_da` a `(H,W)` al final.
- **`@torch.no_grad()` / `eval()`**: correcto para inferencia; reduce memoria y desactiva dropout/BN en modo train.

**Ejemplo**
```python
L = 18
prob_fut, bin_fut = forecast_future(student_all, net_tcnn, L=L, steps=12, thr=0.5, resize_to=(512,512))

"""

@torch.no_grad()
def make_input_stack(frames_L, resize_to=None):
    """frames_L: lista/array [L,H,W] 0/1 → tensor [1,L,H,W] listo para la red."""
    arr = np.stack(frames_L, axis=0).astype(np.float32)  # [L,H,W]
    if resize_to is not None:
        h,w = resize_to
        arr_rs = [resize(arr[k], (h,w), order=0, preserve_range=True, anti_aliasing=False) for k in range(arr.shape[0])]
        arr = np.stack(arr_rs, axis=0)
    x = torch.from_numpy(to_c_array(arr)).unsqueeze(0)    # [1,L,H,W]
    return x

def monthly_range_after(last_time, n_months):
    start = pd.Period(pd.to_datetime(last_time), freq='M') + 1
    per = pd.period_range(start, periods=n_months, freq='M')
    return list(per.to_timestamp())

@torch.no_grad()
def forecast_future(student_all, net, L=6, steps=6, thr=0.5, resize_to=(512,512), device=None):
    """
    Autoregresivo L->1 por pasos; usa las últimas L observaciones y va avanzando 'steps' meses.
    Devuelve (prob_da, bin_da) con dims ('time','Y','X') en la grilla (posiblemente redimensionada).
    """
    device = device or ('cuda' if torch.cuda.is_available() else 'cpu')
    net.eval()
    X, Y = xy_dims(student_all)
    times = pd.to_datetime(student_all['time'].values)
    H, W = student_all.sizes[Y], student_all.sizes[X]

    # buffer con últimas L
    hist = to_c_array(student_all.transpose('time', Y, X).values, dtype=np.float32)  # [T,H,W]
    buf = [hist[-L+k, :, :] for k in range(L)]  # lista de [H,W]

    fut_times = monthly_range_after(times[-1], steps)
    prob_maps, bin_maps = [], []

    for t in fut_times:
        x = make_input_stack(buf, resize_to=resize_to).to(device)
        p = torch.sigmoid(net(x)).cpu().numpy()[0,0]  # [H',W'] si resize_to
        b = (p >= thr).astype(np.uint8)

        prob_maps.append(p)
        bin_maps.append(b)

        # para el siguiente paso, agrego el binario (autoregresivo)
        # si redimensioné, también debo redimensionar de vuelta a H,W para mantener el buffer
        next_for_buf = b
        if resize_to is not None and (resize_to != (H,W)):
            next_for_buf = resize(next_for_buf, (H,W), order=0, preserve_range=True, anti_aliasing=False).astype(np.uint8)
        buf = buf[1:] + [next_for_buf]

    # coords de salida
    if resize_to is None:
        Yc, Xc = student_all[Y], student_all[X]
    else:
        Yc = np.arange(resize_to[0]); Xc = np.arange(resize_to[1])

    prob_da = xr.DataArray(np.stack(prob_maps, axis=0), coords={'time': fut_times, Y: Yc, X: Xc},
                           dims=('time', Y, X), name='prob')
    bin_da  = xr.DataArray(np.stack(bin_maps,  axis=0).astype(np.uint8), coords={'time': fut_times, Y: Yc, X: Xc},
                           dims=('time', Y, X), name='bin')
    return prob_da, bin_da

# Ejemplo: predecir próximos 12 meses
prob_fut, bin_fut = forecast_future(student_all, net_tcnn, L=L, steps=12, thr=0.5, resize_to=(512,512))

bin_fut

prob_fut

def _xy_dims(da):
    X = 'X' if 'X' in da.dims else ('x' if 'x' in da.dims else None)
    Y = 'Y' if 'Y' in da.dims else ('y' if 'y' in da.dims else None)
    if X is None or Y is None:
        raise ValueError("No encuentro dims espaciales 'X'/'Y' (o 'x'/'y').")
    return X, Y

def _axis_formatter(vals, axis_name='X'):
    vmax = float(np.nanmax(np.abs(vals)))
    if vmax >= 1e6:        # metros grandes → millones
        div, unit, fmt = 1e6, '×10⁶ m', '{:.3f}'
    elif vmax >= 1e3:      # ~km
        div, unit, fmt = 1e3, 'km', '{:.0f}'
    else:                  # píxeles/met. chicos
        div, unit, fmt = 1.0, 'px', '{:.0f}'
    formatter = FuncFormatter(lambda v, pos: fmt.format(v / div))
    label = f'{axis_name} ({unit})'
    return formatter, label

def _month_es_labels(times):
    # etiquetas en español (Ene, Feb, …)
    abbr = np.array(['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'])
    t = pd.to_datetime(times)
    return [f"{abbr[m-1]} {y}" for m, y in zip(t.month, t.year)]

def plot_prob_maps(prob, col_wrap=4, vmin=0.0, vmax=1.0, cmap='viridis',
                   per_panel_colorbar=True, cbar_fraction=0.028, cbar_pad=0.01,
                   overlay_thr=None, overlay_color='white', overlay_lw=0.6):
    """
    prob: xarray.DataArray con dims ('time','Y','X') o ('time','y','x'), valores [0..1]
    overlay_thr: si se pasa un float (p.ej. 0.5), dibuja la isocurva de prob=thr
    """
    assert 'time' in prob.dims, "Se requiere dim 'time'."
    X, Y = _xy_dims(prob)

    xv, yv = prob[X].values, prob[Y].values
    extent = (float(np.nanmin(xv)), float(np.nanmax(xv)),
              float(np.nanmin(yv)), float(np.nanmax(yv)))
    origin = 'lower' if (yv.size > 1 and (yv[1]-yv[0]) > 0) else 'upper'

    fmt_x, lab_x = _axis_formatter(xv, 'X')
    fmt_y, lab_y = _axis_formatter(yv, 'Y')

    times = pd.to_datetime(prob['time'].values)
    titles = _month_es_labels(times)

    T = len(times)
    cols = col_wrap
    rows = math.ceil(T/cols)
    fig, axes = plt.subplots(rows, cols, figsize=(4.2*cols, 4.2*rows), squeeze=False)
    axes = axes.ravel()

    ims = []
    for i, (t, ttl) in enumerate(zip(times, titles)):
        ax = axes[i]
        img = prob.sel(time=t).transpose(Y, X).values
        im = ax.imshow(img, vmin=vmin, vmax=vmax, cmap=cmap,
                       extent=extent, origin=origin,
                       interpolation='nearest', rasterized=True)
        ims.append(im)

        # ejes
        ax.set_title(ttl, fontsize=10)
        ax.set_xlabel(lab_x); ax.set_ylabel(lab_y)
        ax.xaxis.set_major_formatter(fmt_x); ax.yaxis.set_major_formatter(fmt_y)
        ax.xaxis.set_major_locator(MaxNLocator(5)); ax.yaxis.set_major_locator(MaxNLocator(5))
        ax.tick_params(axis='x', labelrotation=45)
        ax.set_aspect('equal')

        # colorbar por panel (opcional)
        if per_panel_colorbar:
            cb = fig.colorbar(im, ax=ax, fraction=cbar_fraction, pad=cbar_pad)
            cb.set_label('Prob. agua (0–1)')

        # contorno opcional (isocurva de prob)
        if overlay_thr is not None and np.isfinite(overlay_thr):
            try:
                cs = ax.contour(img, levels=[overlay_thr], colors=overlay_color,
                                linewidths=overlay_lw, extent=extent, origin=origin)
            except Exception:
                pass

    # ocultar sobrantes
    for j in range(T, len(axes)):
        axes[j].axis('off')

    # si querés una única barra compartida, pon per_panel_colorbar=False
    if not per_panel_colorbar and ims:
        cbar = fig.colorbar(ims[0], ax=[ax for ax in axes[:T]], fraction=0.03, pad=0.02)
        cbar.set_label('Prob. agua (0–1)')

    plt.tight_layout()
    plt.show()

plot_prob_maps(bin_fut, col_wrap=2, cmap='viridis', per_panel_colorbar=True)

