"""# Estacionalidades Espaciales"""

def water_occurrence(student_all, thr=0.5):
    da = student_all
    X = 'X' if 'X' in da.dims else 'x'; Y = 'Y' if 'Y' in da.dims else 'y'
    if np.issubdtype(da.dtype, np.floating):
        bin_da = (da >= thr).astype('float32')
    else:
        bin_da = (da > 0).astype('float32')
    occ = bin_da.mean(dim='time', skipna=True).rename('occurrence')
    return occ

def monthly_probability(student_all, thr=0.5):
    da = student_all
    X = 'X' if 'X' in da.dims else 'x'; Y = 'Y' if 'Y' in da.dims else 'y'
    if np.issubdtype(da.dtype, np.floating):
        bin_da = (da >= thr).astype('float32')
    else:
        bin_da = (da > 0).astype('float32')
    num   = bin_da.groupby('time.month').sum('time', skipna=True)
    denom = bin_da.groupby('time.month').count('time')
    probm = (num / xr.where(denom==0, np.nan, denom)).transpose('month', Y, X)
    probm = probm.rename('prob_month')
    return probm
def water_recurrence(student_all, thr=0.5):
    da = student_all
    X = 'X' if 'X' in da.dims else 'x'; Y = 'Y' if 'Y' in da.dims else 'y'
    if np.issubdtype(da.dtype, np.floating):
        w = (da >= thr).astype('uint8')
    else:
        w = (da > 0).astype('uint8')

    # indices tiempo
    t = np.arange(w.sizes['time'], dtype=np.int32)
    def _rec_one(ts):
        # ts: (time,) -> 0/1 con NaN manejado como 0
        arr = np.nan_to_num(ts.astype(np.float32), nan=0.0).astype(np.uint8)
        idx = np.where(arr==1)[0]
        if idx.size==0:
            return np.nan
        win = idx[-1]-idx[0]+1
        return float(arr.sum())/float(win) if win>0 else np.nan

    # vectorizar por píxel
    rec = xr.apply_ufunc(
        _rec_one, w,
        input_core_dims=[['time']],
        output_dtypes=[float],
        vectorize=True
    ).rename('recurrence')
    return rec

def harmonic_seasonality_v2(probm):
    """
    probm: DataArray con dims ('month','Y','X') o ('month','y','x')
           valores en [0,1] = probabilidad mensual histórica.
    Devuelve:
      - amp:   amplitud del 1er armónico (misma forma que un frame espacial)
      - pmon:  mes pico (1..12, continuo) donde el 1er armónico alcanza el máximo
    """
    if not isinstance(probm, xr.DataArray):
        raise TypeError("Se espera xarray.DataArray en 'probm'.")
    if 'month' not in probm.dims:
        raise ValueError("Falta la dimensión 'month' en 'probm'.")

    # Detección de dims espaciales
    X = 'X' if 'X' in probm.dims else ('x' if 'x' in probm.dims else None)
    Y = 'Y' if 'Y' in probm.dims else ('y' if 'y' in probm.dims else None)
    if X is None or Y is None:
        raise ValueError("No encuentro dims espaciales 'X'/'Y' (o 'x'/'y').")

    # Base trigonométrica (DataArray, no ndarray)
    m = probm['month'].astype(float)                     # (month,)
    w = 2.0 * np.pi / 12.0
    cos1 = xr.apply_ufunc(np.cos, w * m).rename('cos1')  # (month,)
    sin1 = xr.apply_ufunc(np.sin, w * m).rename('sin1')  # (month,)

    # Coeficientes del primer armónico: a1, b1
    # a1 = (2/N) * sum_m p_m * cos(ωm), b1 = (2/N) * sum_m p_m * sin(ωm)
    N = 12.0
    a1 = (2.0 / N) * (probm * cos1).sum('month', skipna=True)
    b1 = (2.0 / N) * (probm * sin1).sum('month', skipna=True)

    # Amplitud y fase
    amp = xr.apply_ufunc(np.hypot, a1, b1).rename('season_amp')   # (Y,X)
    phi = xr.apply_ufunc(np.arctan2, b1, a1)                      # [-pi, pi]

    # Mes pico (1..12, continuo). Llevar fase a [0, 2π) y mapear a meses (1..12]
    phi_pos = (phi + 2*np.pi) % (2*np.pi)
    peak_month = (12.0 * phi_pos / (2*np.pi))                     # [0,12)
    peak_month = (peak_month % 12) + 1.0                          # (0,12] -> 1..12
    peak_month = peak_month.rename('peak_month')

    # Mantener orden de dims espacial
    amp  = amp.transpose(Y, X)
    peak_month = peak_month.transpose(Y, X)
    return amp, peak_month


def cluster_zones(occ, rec, amp, peak_month, n_clusters=4, mask_min_obs=None):
    # peak as 2D circular
    cosm = xr.apply_ufunc(np.cos, 2*np.pi*peak_month/12.0)
    sinm = xr.apply_ufunc(np.sin, 2*np.pi*peak_month/12.0)
    # stack
    feat = xr.concat([occ, rec, amp, cosm, sinm], dim='feat').transpose('feat', ...)
    arr = feat.values.reshape(5, -1).T  # [Npix, 5]
    valid = np.all(np.isfinite(arr), axis=1)
    km = KMeans(n_clusters=n_clusters, random_state=0).fit(arr[valid])
    lab = np.full(arr.shape[0], -1, dtype=np.int16); lab[valid] = km.labels_
    lab2d = lab.reshape(occ.sizes['Y'], occ.sizes['X'])
    return xr.DataArray(lab2d, coords={ 'Y': occ['Y'], 'X': occ['X']}, dims=('Y','X'), name='zone')

# 1) métricas
occ = water_occurrence(student_all, thr=0.5)
probm = monthly_probability(student_all, thr=0.5)
rec  = water_recurrence(student_all, thr=0.5)

