# -------- helpers de ejes/extent --------
def _xy_dims(da):
    X = 'X' if 'X' in da.dims else ('x' if 'x' in da.dims else None)
    Y = 'Y' if 'Y' in da.dims else ('y' if 'y' in da.dims else None)
    if X is None or Y is None:
        raise ValueError("No encuentro dims espaciales 'X'/'Y' (o 'x'/'y').")
    return X, Y

def _axis_formatter(vals, axis_name='X'):
    vmax = float(np.nanmax(np.abs(vals)))
    if vmax >= 1e6:        div, unit, fmt = 1e6, '×10⁶ m', '{:.3f}'
    elif vmax >= 1e3:      div, unit, fmt = 1e3, 'km',      '{:.0f}'
    else:                  div, unit, fmt = 1.0, 'px',      '{:.0f}'
    formatter = FuncFormatter(lambda v, pos: fmt.format(v/div))
    label = f'{axis_name} ({unit})'
    return formatter, label

def _extent_origin(da2d):
    X, Y = _xy_dims(da2d)
    xv, yv = da2d[X].values, da2d[Y].values
    extent = (float(np.nanmin(xv)), float(np.nanmax(xv)),
              float(np.nanmin(yv)), float(np.nanmax(yv)))
    origin = 'lower' if (yv.size>1 and (yv[1]-yv[0])>0) else 'upper'
    return extent, origin, X, Y

# -------- 1) OCCURRENCIA / RECURRENCIA --------
def plot_occurrence(occ, cmap='Blues'):
    extent, origin, X, Y = _extent_origin(occ)
    fmt_x, lab_x = _axis_formatter(occ[X].values, 'X')
    fmt_y, lab_y = _axis_formatter(occ[Y].values, 'Y')
    plt.figure(figsize=(6,5))
    ax = plt.gca()
    im = ax.imshow(occ.transpose(Y,X).values, vmin=0, vmax=1, cmap=cmap,
                   extent=extent, origin=origin, interpolation='nearest', rasterized=True)
    ax.set_title('Ocurrencia (fracción de tiempo con agua)')
    ax.set_xlabel(lab_x); ax.set_ylabel(lab_y)
    ax.xaxis.set_major_formatter(fmt_x); ax.yaxis.set_major_formatter(fmt_y)
    ax.xaxis.set_major_locator(MaxNLocator(5)); ax.yaxis.set_major_locator(MaxNLocator(5))
    ax.tick_params(axis='x', labelrotation=45)
    ax.set_aspect('equal')
    cb = plt.colorbar(im); cb.set_label('0–1')
    plt.tight_layout(); plt.show()

def plot_recurrence(rec, cmap='Greens'):
    extent, origin, X, Y = _extent_origin(rec)
    fmt_x, lab_x = _axis_formatter(rec[X].values, 'X')
    fmt_y, lab_y = _axis_formatter(rec[Y].values, 'Y')
    plt.figure(figsize=(6,5))
    ax = plt.gca()
    im = ax.imshow(rec.transpose(Y,X).values, vmin=0, vmax=1, cmap=cmap,
                   extent=extent, origin=origin, interpolation='nearest', rasterized=True)
    ax.set_title('Recurrencia (frecuencia dentro del período con agua)')
    ax.set_xlabel(lab_x); ax.set_ylabel(lab_y)
    ax.xaxis.set_major_formatter(fmt_x); ax.yaxis.set_major_formatter(fmt_y)
    ax.xaxis.set_major_locator(MaxNLocator(5)); ax.yaxis.set_major_locator(MaxNLocator(5))
    ax.tick_params(axis='x', labelrotation=45)
    ax.set_aspect('equal')
    cb = plt.colorbar(im); cb.set_label('0–1')
    plt.tight_layout(); plt.show()

# -------- 2) PROBABILIDAD MENSUAL 12 paneles --------
def plot_probm_12panels(probm, col_wrap=4, cmap='viridis', per_panel_colorbar=True,
                        cbar_fraction=0.028, cbar_pad=0.01):
    assert 'month' in probm.dims
    extent, origin, X, Y = _extent_origin(probm.isel(month=0))
    fmt_x, lab_x = _axis_formatter(probm[X].values, 'X')
    fmt_y, lab_y = _axis_formatter(probm[Y].values, 'Y')

    months = list(probm['month'].values)
    names  = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic']
    n = len(months); cols = col_wrap; rows = math.ceil(n/cols)
    fig, axes = plt.subplots(rows, cols, figsize=(4.0*cols, 4.0*rows), squeeze=False)
    axes = axes.ravel()
    ims = []
    for i, m in enumerate(months):
        ax = axes[i]
        img = probm.sel(month=m).transpose(Y, X).values
        im = ax.imshow(img, vmin=0, vmax=1, cmap=cmap,
                       extent=extent, origin=origin, interpolation='nearest', rasterized=True)
        ims.append(im)
        ax.set_title(names[m-1], fontsize=10)
        ax.set_xlabel(lab_x); ax.set_ylabel(lab_y)
        ax.xaxis.set_major_formatter(fmt_x); ax.yaxis.set_major_formatter(fmt_y)
        ax.xaxis.set_major_locator(MaxNLocator(5)); ax.yaxis.set_major_locator(MaxNLocator(5))
        ax.tick_params(axis='x', labelrotation=45)
        ax.set_aspect('equal')
        if per_panel_colorbar:
            cb = fig.colorbar(im, ax=ax, fraction=cbar_fraction, pad=cbar_pad)
            cb.set_label('Prob. (0–1)')
    for j in range(n, len(axes)): axes[j].axis('off')
    if not per_panel_colorbar and ims:
        cbar = fig.colorbar(ims[0], ax=[ax for ax in axes[:n]], fraction=0.03, pad=0.02)
        cbar.set_label('Prob. (0–1)')
    plt.tight_layout(); plt.show()

# -------- 3) ESTACIONALIDAD: amplitud y mes pico --------
def plot_seasonality(amp, peak):
    # amp: (Y,X), peak: (Y,X) con 1..12
    extent, origin, X, Y = _extent_origin(amp)
    fmt_x, lab_x = _axis_formatter(amp[X].values, 'X')
    fmt_y, lab_y = _axis_formatter(amp[Y].values, 'Y')

    fig, axes = plt.subplots(1, 2, figsize=(10,4.2))
    # Amplitud (0..~0.5)
    ax = axes[0]
    vmax = float(np.nanpercentile(amp.values, 99))
    im = ax.imshow(amp.transpose(Y,X).values, vmin=0, vmax=vmax, cmap='magma',
                   extent=extent, origin=origin, interpolation='nearest', rasterized=True)
    ax.set_title('Amplitud estacional (1er armónico)')
    ax.set_xlabel(lab_x); ax.set_ylabel(lab_y)
    ax.xaxis.set_major_formatter(fmt_x); ax.yaxis.set_major_formatter(fmt_y)
    ax.tick_params(axis='x', labelrotation=45); ax.set_aspect('equal')
    cb = plt.colorbar(im, ax=ax, fraction=0.046, pad=0.02); cb.set_label('amplitud')

    # Mes pico (1..12) con colormap cíclico
    ax = axes[1]
    im2 = ax.imshow(peak.transpose(Y,X).values, vmin=1, vmax=12, cmap='hsv',
                    extent=extent, origin=origin, interpolation='nearest', rasterized=True)
    ax.set_title('Mes pico (máxima probabilidad)')
    ax.set_xlabel(lab_x); ax.set_ylabel('')
    ax.yaxis.set_ticklabels([]); ax.xaxis.set_major_formatter(fmt_x)
    ax.tick_params(axis='x', labelrotation=45); ax.set_aspect('equal')
    cbar = plt.colorbar(im2, ax=ax, fraction=0.046, pad=0.02)
    cbar.set_label('Mes'); cbar.set_ticks([1,3,5,7,9,11])
    cbar.set_ticklabels(['Ene','Mar','May','Jul','Sep','Nov'])

    plt.tight_layout(); plt.show()

# -------- 4) CLASES CATEGÓRICAS --------
def plot_classes(classes):
    # 0 esporádico, 1 estacional, 2 permanente; -1 = sin clase
    extent, origin, X, Y = _extent_origin(classes)
    fmt_x, lab_x = _axis_formatter(classes[X].values, 'X')
    fmt_y, lab_y = _axis_formatter(classes[Y].values, 'Y')

    data = classes.transpose(Y,X).values
    mask = (data < 0) | ~np.isfinite(data)
    # Colores
    colors = ['#FDE725', '#24AA83', '#2C7FB8']  # 0,1,2
    cmap = ListedColormap(colors)
    norm = BoundaryNorm([-0.5,0.5,1.5,2.5], cmap.N)
    plt.figure(figsize=(6.2,5))
    ax = plt.gca()
    im = ax.imshow(np.ma.masked_where(mask, data), cmap=cmap, norm=norm,
                   extent=extent, origin=origin, interpolation='nearest', rasterized=True)
    ax.set_title('Clases: 0 esporádico | 1 estacional | 2 permanente')
    ax.set_xlabel(lab_x); ax.set_ylabel(lab_y)
    ax.xaxis.set_major_formatter(fmt_x); ax.yaxis.set_major_formatter(fmt_y)
    ax.xaxis.set_major_locator(MaxNLocator(5)); ax.yaxis.set_major_locator(MaxNLocator(5))
    ax.tick_params(axis='x', labelrotation=45); ax.set_aspect('equal')

    # leyenda manual
    import matplotlib.patches as mpatches
    patches = [mpatches.Patch(color=colors[i], label=lab) for i,lab in
               enumerate(['0 Esporádico','1 Estacional','2 Permanente'])]
    ax.legend(handles=patches, loc='lower right', frameon=True)
    plt.tight_layout(); plt.show()

# -------- 5) ZONAS (clustering) --------
def plot_zones(zones, cmap='tab20'):
    extent, origin, X, Y = _extent_origin(zones)
    fmt_x, lab_x = _axis_formatter(zones[X].values, 'X')
    fmt_y, lab_y = _axis_formatter(zones[Y].values, 'Y')

    vals = zones.transpose(Y,X).values
    plt.figure(figsize=(6.2,5))
    ax = plt.gca()
    im = ax.imshow(vals, cmap=cmap, interpolation='nearest', rasterized=True,
                   extent=extent, origin=origin)
    ax.set_title('Zonas (clustering de firmas temporales)')
    ax.set_xlabel(lab_x); ax.set_ylabel(lab_y)
    ax.xaxis.set_major_formatter(fmt_x); ax.yaxis.set_major_formatter(fmt_y)
    ax.xaxis.set_major_locator(MaxNLocator(5)); ax.yaxis.set_major_locator(MaxNLocator(5))
    ax.tick_params(axis='x', labelrotation=45); ax.set_aspect('equal')

    # leyenda con etiquetas únicas
    import matplotlib.patches as mpatches
    uniq = np.unique(vals[np.isfinite(vals)])
    colors = [plt.cm.get_cmap(cmap)(int(u) % plt.cm.get_cmap(cmap).N) for u in uniq]
    patches = [mpatches.Patch(color=c, label=f'Cluster {int(u)}') for u,c in zip(uniq, colors)]
    ax.legend(handles=patches, loc='lower right', frameon=True)
    plt.tight_layout(); plt.show()

plot_occurrence(occ)
plot_recurrence(rec)
plot_probm_12panels(probm, col_wrap=2)

plot_seasonality(amp, peak)

plot_classes(classes)
plot_zones(zones)

"""# Animaciones"""

from matplotlib.animation import FuncAnimation, PillowWriter
import matplotlib.dates as mdates

def make_area_progress_gif(
    df_area,
    out_path="area_progress.gif",
    fps=2.0,
    dpi=140,
    title="Evolución de superficie de agua",
    line_color="#1f77b4",
    head_color="#d62728",
):
    """
    df_area: DataFrame con columnas ['time','area_km2']
    Crea un GIF donde se animan los puntos/segmentos de la serie de tiempo.
    """
    # --- preparar datos ---
    df = df_area.copy()
    df["time"] = pd.to_datetime(df["time"])
    df = df.sort_values("time")
    df = df.dropna(subset=["area_km2"])
    df = df[~df["time"].duplicated(keep="first")]  # por si hay repetidos exactos

    t = df["time"].to_numpy()
    y = df["area_km2"].to_numpy()
    n = len(df)
    if n == 0:
        raise ValueError("df_area no tiene datos válidos.")
    if n == 1:
        # con un solo punto, duplico para que la animación tenga al menos 2 frames
        t = np.append(t, t[0])
        y = np.append(y, y[0])
        n = 2

    # --- figura y ejes ---
    fig, ax = plt.subplots(figsize=(8.5, 4.2))
    ax.set_title(title)
    ax.set_xlabel("Fecha")
    ax.set_ylabel("Área (km²)")
    ax.grid(alpha=0.3)

    # formato de fechas
    ax.xaxis.set_major_locator(mdates.AutoDateLocator(minticks=4, maxticks=8))
    ax.xaxis.set_major_formatter(mdates.ConciseDateFormatter(ax.xaxis.get_major_locator()))

    # límites fijos para que no “salte” el eje en la animación
    ypad = 0.05 * (np.nanmax(y) - np.nanmin(y) if np.nanmax(y) != np.nanmin(y) else 1.0)
    ax.set_ylim(np.nanmin(y) - ypad, np.nanmax(y) + ypad)
    ax.set_xlim(t[0], t[-1])

    # artistas a actualizar
    line, = ax.plot([], [], color=line_color, lw=2, marker="o", ms=3)
    head, = ax.plot([], [], "o", color=head_color, ms=7)
    txt = ax.text(0.02, 0.95, "", transform=ax.transAxes, va="top")

    # fondo tenue con toda la serie (opcional; ayuda a ver el contexto)
    ax.plot(t, y, color="#bbbbbb", lw=1, alpha=0.6)

    def init():
        line.set_data([], [])
        head.set_data([], [])
        txt.set_text("")
        return line, head, txt

    def update(i):
        # i recorre 0..n-1 y mostramos hasta i
        line.set_data(t[: i + 1], y[: i + 1])
        head.set_data([t[i]], [y[i]])  # ► secuencias, no escalares
        txt.set_text(f"{pd.to_datetime(t[i]).strftime('%Y-%m-%d')}\nÁrea: {y[i]:.3f} km²")
        return line, head, txt

    anim = FuncAnimation(fig, update, frames=n, init_func=init, blit=False, interval=1000/fps)
    anim.save(out_path, writer=PillowWriter(fps=fps), dpi=dpi)
    plt.close(fig)
    print(f"GIF guardado en: {out_path}")

