import io, math, os
import numpy as np
import pandas as pd
import xarray as xr
import matplotlib.pyplot as plt
from matplotlib.ticker import FuncFormatter
from PIL import Image

# ---------------- helpers coord-aware ----------------
def _to_datetime(v):
    return pd.to_datetime(np.asarray(v))

def _xy_dims(da):
    # busca 'X'/'Y' o variantes
    cand = [d for d in da.dims if d.lower() not in ("time","band")]
    if len(cand) != 2:
        raise ValueError(f"Se esperaban 2 dims espaciales, obtuve: {cand}")
    # intentamos devolver ('X','Y') si existen
    if 'X' in da.dims and 'Y' in da.dims:
        return 'X','Y'
    # en caso contrario, respetar el orden presente
    # y los llamamos (X,Y) por convenio
    return cand[1], cand[0] if cand[0].lower().startswith('y') else cand[0], cand[1]

def _pick_rgb_bands(ds):
    # Devuelve dict {'R','G','B'} con DataArrays (time,Y,X)
    if isinstance(ds, xr.Dataset):
        for names in (["SR_B5","SR_B4","SR_B3"],
                      ["B5_NIR","B4_RED","B3_GREEN"],
                      ["B5","B4","B3"]):
            if all(n in ds.data_vars for n in names):
                return {
                    'R': ds[names[0]],
                    'G': ds[names[1]],
                    'B': ds[names[2]],
                }
    if isinstance(ds, xr.DataArray) and ('band' in ds.dims):
        bands = [str(b) for b in ds['band'].values]
        for names in (["SR_B5","SR_B4","SR_B3"],
                      ["B5_NIR","B4_RED","B3_GREEN"],
                      ["B5","B4","B3"]):
            if all(n in bands for n in names):
                return {
                    'R': ds.sel(band=names[0]),
                    'G': ds.sel(band=names[1]),
                    'B': ds.sel(band=names[2]),
                }
    raise ValueError("No se encontraron bandas 5/4/3 en a_m_sync.")

def _stretch01(a, lo, hi):
    a = (a - lo) / max(hi - lo, 1e-6)
    return np.clip(a, 0, 1)

def _robust_rgb(R, G, B, p=(2,98), per_frame=False, globals_=None):
    # Devuelve tripleta [0,1] con stretch robusto
    Rn = np.nan_to_num(R, nan=np.nanmedian(R))
    Gn = np.nan_to_num(G, nan=np.nanmedian(G))
    Bn = np.nan_to_num(B, nan=np.nanmedian(B))
    if p is None:
        return np.clip(np.dstack([Rn,Gn,Bn]), 0, 1)
    if per_frame:
        lR,hR = np.nanpercentile(Rn, p); lG,hG = np.nanpercentile(Gn, p); lB,hB = np.nanpercentile(Bn, p)
    else:
        lR,hR,lG,hG,lB,hB = globals_
    return np.dstack([_stretch01(Rn,lR,hR), _stretch01(Gn,lG,hG), _stretch01(Bn,lB,hB)])

def _to_prob(arr):
    arr = np.nan_to_num(arr, nan=0.0)
    q1, q99 = np.nanpercentile(arr, [1,99])
    looks_logits = (q99 > 1.2) or (np.nanmin(arr) < 0)
    if looks_logits:
        arr = 1.0 / (1.0 + np.exp(-arr))  # sigmoid
    return np.clip(arr, 0.0, 1.0)

def _compute_ndwi_from_rgb(R, B):
    # R = NIR (B5), B = GREEN (B3)
    num = B - R
    den = B + R
    return np.where(np.abs(den) > 1e-6, num/den, 0.0)

# ---------------- función principal coord-aware ----------------
def make_triplet_gif_seq_coords(
    a_m_sync, student_all, ndwi_da=None,
    out_gif="tripletes_seq.gif",
    out_frames_dir=None,
    times=None,           # lista/array de fechas; si None usa intersección completa
    k=None, seed=None,    # si k no es None, toma k fechas al azar
    fps=1.5, dpi=140,
    rgb_p=(2,98), per_frame_stretch=False,
    ndwi_range=(-0.6,0.6),
    student_view="prob",  # "prob" | "bin" | "auto"
    thr=0.5
):
    # --- tiempos comunes ---
    t_rgb = _to_datetime(a_m_sync['time'].values)
    t_stu = _to_datetime(student_all['time'].values)
    common = np.intersect1d(t_rgb.values, t_stu.values)
    if ndwi_da is not None:
        t_ndw = _to_datetime(ndwi_da['time'].values)
        common = np.intersect1d(common, t_ndw.values)
    if common.size == 0:
        raise ValueError("No hay tiempos en común entre RGB, Student (y NDWI).")

    if times is not None:
        pick = np.intersect1d(common, _to_datetime(times).values)
    elif k is not None:
        rng = np.random.default_rng(seed)
        pick = rng.choice(common, size=min(k, common.size), replace=False)
    else:
        pick = common
    pick = np.sort(pick)

    # --- preparar RGB y NDWI ---
    rgb = _pick_rgb_bands(a_m_sync)  # {'R','G','B'}
    sel = dict(time=pick)
    R = rgb['R'].sel(**sel)
    G = rgb['G'].sel(**sel)
    B = rgb['B'].sel(**sel)

    # NDWI como DataArray en la misma grilla/coords
    if ndwi_da is None:
        Nd = xr.apply_ufunc(
            _compute_ndwi_from_rgb, R, B,
            input_core_dims=[[],[]], dask='parallelized', vectorize=True
        )
    else:
        Nd = ndwi_da.sel(**sel)

    # Student alineado
    Stu = student_all.sel(time=pick)

    # --- extent y orientación desde coords ---
    X, Y = _xy_dims(R)
    xv = R[X].values; yv = R[Y].values
    extent = (float(xv.min()), float(xv.max()), float(yv.min()), float(yv.max()))
    origin = 'lower' if (yv.size>1 and (yv[1]-yv[0])>0) else 'upper'
    fmt_mill = FuncFormatter(lambda v, pos: f"{v/1e6:.3f}")

    # --- percentiles globales para RGB si corresponde ---
    globals_rgb = None
    if (rgb_p is not None) and (not per_frame_stretch):
        Rall = R.values.reshape(-1)
        Gall = G.values.reshape(-1)
        Ball = B.values.reshape(-1)
        lR,hR = np.nanpercentile(Rall, rgb_p)
        lG,hG = np.nanpercentile(Gall, rgb_p)
        lB,hB = np.nanpercentile(Ball, rgb_p)
        globals_rgb = (lR,hR,lG,hG,lB,hB)

    # --- generar frames ---
    frames = []
    if out_frames_dir:
        os.makedirs(out_frames_dir, exist_ok=True)

    for t in pick:
        # extraer arrays en orden (Y,X)
        Rt = R.sel(time=t).transpose(Y, X).values
        Gt = G.sel(time=t).transpose(Y, X).values
        Bt = B.sel(time=t).transpose(Y, X).values
        Nd_t = Nd.sel(time=t).transpose(Y, X).values
        St = Stu.sel(time=t).transpose(Y, X).values.astype('float32')

        # RGB con stretch
        rgb_img = _robust_rgb(Rt, Gt, Bt, p=rgb_p,
                              per_frame=per_frame_stretch,
                              globals_=globals_rgb)

        # NDWI y Student limpios
        Nd_t = np.clip(np.nan_to_num(Nd_t, nan=0.0), ndwi_range[0], ndwi_range[1])
        if student_view == "bin":
            St_show = (St >= thr).astype('float32') if np.issubdtype(St.dtype, np.floating) else (St > 0).astype('float32')
            cmapS, vminS, vmaxS = 'gray', 0, 1
        elif student_view == "auto":
            St_bin = (St >= thr).astype('float32') if np.issubdtype(St.dtype, np.floating) else (St > 0).astype('float32')
            if St_bin.sum() == 0:
                St_show = _to_prob(St); cmapS, vminS, vmaxS = 'viridis', 0, 1
            else:
                St_show = St_bin; cmapS, vminS, vmaxS = 'gray', 0, 1
        else:  # "prob"
            St_show = _to_prob(St); cmapS, vminS, vmaxS = 'viridis', 0, 1

        # figura (coordenadas reales, sin giros/flip)
        fig = plt.figure(figsize=(12,4), dpi=dpi)
        ax1 = fig.add_subplot(1,3,1)
        ax2 = fig.add_subplot(1,3,2)
        ax3 = fig.add_subplot(1,3,3)

        ax1.imshow(rgb_img, extent=extent, origin=origin, interpolation='nearest')
        ax1.set_title(f"RGB 5-4-3 — {pd.to_datetime(t).strftime('%Y-%m')}")
        ax1.set_xlabel('X (×10⁶ m)'); ax1.set_ylabel('Y (×10⁶ m)')
        ax1.xaxis.set_major_formatter(fmt_mill); ax1.yaxis.set_major_formatter(fmt_mill)
        ax1.tick_params(axis='x', labelrotation=45); ax1.set_aspect('equal')

        im2 = ax2.imshow(Nd_t, extent=extent, origin=origin,
                         vmin=ndwi_range[0], vmax=ndwi_range[1], cmap='RdBu_r', interpolation='nearest')
        ax2.set_title("NDWI"); ax2.set_xlabel('X (×10⁶ m)'); ax2.set_ylabel('')
        ax2.yaxis.set_ticklabels([]); ax2.xaxis.set_major_formatter(fmt_mill)
        ax2.tick_params(axis='x', labelrotation=45); ax2.set_aspect('equal')
        cbar2 = plt.colorbar(im2, ax=ax2, fraction=0.046, pad=0.02); cbar2.ax.set_ylabel('NDWI')

        im3 = ax3.imshow(St_show, extent=extent, origin=origin,
                         vmin=vminS, vmax=vmaxS, cmap=cmapS, interpolation='nearest')
        ax3.set_title("Student"); ax3.set_xlabel('X (×10⁶ m)'); ax3.set_ylabel('')
        ax3.yaxis.set_ticklabels([]); ax3.xaxis.set_major_formatter(fmt_mill)
        ax3.tick_params(axis='x', labelrotation=45); ax3.set_aspect('equal')
        cbar3 = plt.colorbar(im3, ax=ax3, fraction=0.046, pad=0.02); cbar3.ax.set_ylabel('prob/0-1')

        plt.tight_layout()

        # a buffer -> PIL -> lista de frames
        buf = io.BytesIO()
        fig.savefig(buf, format='png', bbox_inches='tight', pad_inches=0.05)
        plt.close(fig)
        buf.seek(0)
        img = Image.open(buf).convert('P', palette=Image.ADAPTIVE)
        frames.append(img)
        if out_frames_dir:
            img.save(os.path.join(out_frames_dir, f"frame_{pd.to_datetime(t):%Y%m}.png"))

    # --- guardar GIF ---
    if not frames:
        raise RuntimeError("No se generaron frames.")
    dur_ms = int(1000/max(fps,0.1))
    frames[0].save(out_gif, save_all=True, append_images=frames[1:],
                   duration=dur_ms, loop=0, optimize=False, disposal=2)
    print(f"GIF guardado en: {out_gif}")

