"""# Cuantiles"""

def _t_dim(da):
    for d in da.dims:
        if d.lower() == 'time':
            return d
    raise ValueError("No encuentro la dimensión 'time'.")

def attach_area_coord(student_da: xr.DataArray, area_s: pd.Series, area_name='area_km2'):
    """
    Adjunta el área como coordenada 'area_km2' (por defecto) a lo largo de 'time'.
    Asume que area_s ya está sincronizada (mismas fechas) con student_da.
    """
    tdim = _t_dim(student_da)
    t_vals = pd.to_datetime(student_da[tdim].values)

    # reindex exacto; si necesitás tolerancia, reemplaza por .reindex(index, method='nearest', tolerance='3D')
    area_aligned = area_s.reindex(t_vals)
    if area_aligned.isna().any():
        raise ValueError("Hay fechas sin área tras reindexar. Revisa sincronización o usa 'method=nearest' con tolerancia.")

    area_da = xr.DataArray(
        area_aligned.values, dims=[tdim], coords={tdim: student_da[tdim]},
        name=area_name, attrs={'units': 'km2'}
    )
    # sumamos como coordenada (también podrías usar assign_vars para dejarlo como variable)
    student_da2 = student_da.assign_coords({area_name: area_da})
    return student_da2

def select_percentile_images(student_da_with_area: xr.DataArray,
                             percentiles=(0.05, 0.10, 0.25, 0.50, 0.75, 0.90, 0.95),
                             area_name='area_km2'):
    """
    Ordena por el área (coordenada) y devuelve:
    - da_sel: DataArray con las imágenes de los percentiles pedidos (dim extra 'q')
    - df_info: DataFrame con (q, time, area)
    """
    tdim = _t_dim(student_da_with_area)
    if area_name not in student_da_with_area.coords:
        raise ValueError(f"No encuentro la coordenada '{area_name}'. ¿Corriste attach_area_coord primero?")

    # vector de áreas y tiempos
    area = student_da_with_area.coords[area_name].values.astype(float)
    times = pd.to_datetime(student_da_with_area[tdim].values)

    # ordenar por área (creciente)
    order = np.argsort(area)
    area_sorted = area[order]
    times_sorted = times[order]

    # umbrales por percentil
    qs = np.array(percentiles, dtype=float)
    targets = np.quantile(area_sorted, qs)

    # para cada target, elegimos el índice con área más cercana, evitando duplicados
    chosen_idx = []
    used = set()
    for tgt in targets:
        dif = np.abs(area_sorted - tgt)
        cand = np.argsort(dif)
        pick = None
        for i in cand:
            if i not in used:
                pick = i
                break
        if pick is None:
            # si todo está usado (muy raro), toma el más cercano igual
            pick = cand[0]
        used.add(pick)
        chosen_idx.append(pick)

    chosen_idx = np.array(chosen_idx, dtype=int)
    chosen_times = times_sorted[chosen_idx]
    chosen_areas = area_sorted[chosen_idx]

    # construir DataArray con dim 'q' (percentil)
    # preservamos dims espaciales tal como vengan
    da_list = [student_da_with_area.sel(**{tdim: t}) for t in chosen_times]
    da_sel = xr.concat(da_list, dim='q')
    da_sel = da_sel.assign_coords(q=('q', qs), time=('q', chosen_times), **{area_name: ('q', chosen_areas)})

    # resumen tabular
    df_info = pd.DataFrame({
        'q': qs,
        'time': chosen_times,
        area_name: chosen_areas
    })
    return da_sel, df_info

def plot_panels_by_dim(da, dim=None, cols=3, cmap='gray', vmin=None, vmax=None,
                       label_x='X (×10⁶ m)', label_y='Y (×10⁶ m)', title_prefix=''):
    """
    Plotea paneles facetando por una dimensión (time, month, q/quantile/percentile, etc.)
    sin asumir que exista 'time'. Usa extent+origin para respetar orientación espacial.
    """
    # --- elegir dims X/Y ---
    dims = list(da.dims)
    X = 'X' if 'X' in dims else ('x' if 'x' in dims else None)
    Y = 'Y' if 'Y' in dims else ('y' if 'y' in dims else None)
    if X is None or Y is None:
        # toma las dos últimas no-facet dims como espaciales
        cand = [d for d in dims if d != dim]
        if len(cand) < 2:
            raise ValueError(f"No encuentro dims espaciales en {dims}")
        Y, X = cand[-2], cand[-1]

    # --- detectar dimensión de faceteo ---
    if dim is None:
        for cand in ['time', 'month', 'q', 'quantile', 'percentile']:
            if cand in dims:
                dim = cand
                break
        if dim is None:
            raise ValueError(f"No encuentro dimensión de faceteo (ni time/month/quantile) en {dims}")

    vals = da[dim].values

    # --- extent & origin (coordenadas reales) ---
    xv = da[X].values
    yv = da[Y].values
    extent = (float(np.nanmin(xv)), float(np.nanmax(xv)),
              float(np.nanmin(yv)), float(np.nanmax(yv)))
    origin = 'lower' if (yv.size > 1 and (yv[1] - yv[0]) > 0) else 'upper'
    fmt_mill = FuncFormatter(lambda v, pos: f"{v/1e6:.3f}")

    # --- grid ---
    n = len(vals)
    cols = max(1, int(cols))
    rows = int(np.ceil(n / cols))
    fig = plt.figure(figsize=(4.2*cols, 4.2*rows))

    def _label(v):
        if dim in ['q','quantile','percentile']:
            # v puede venir como 0.1, 0.25, etc.
            try:
                return f"p{int(round(float(v)*100))}"
            except Exception:
                return str(v)
        if dim == 'month':
            try:
                return pd.Period(int(v), freq='M').strftime('%b')
            except Exception:
                # si v ya es 1..12
                return pd.to_datetime(f'2001-{int(v):02d}-01').strftime('%b')
        if dim == 'time':
            return pd.to_datetime(v).strftime('%Y-%m')
        return str(v)

    for i, v in enumerate(vals):
        ax = fig.add_subplot(rows, cols, i+1)
        img = da.sel({dim: v}).transpose(Y, X).values
        im = ax.imshow(img, extent=extent, origin=origin, cmap=cmap, vmin=vmin, vmax=vmax, interpolation='nearest')
        ax.set_title(f"{title_prefix}{_label(v)}", fontsize=10)
        ax.set_xlabel(label_x); ax.set_ylabel(label_y)
        ax.xaxis.set_major_formatter(fmt_mill); ax.yaxis.set_major_formatter(fmt_mill)
        ax.tick_params(axis='x', labelrotation=45)
        ax.set_aspect('equal')

    # una sola barra de color a la derecha
    cbar = fig.colorbar(im, ax=fig.get_axes(), fraction=0.02, pad=0.01)
    plt.tight_layout()
    plt.show()

df_cmp.set_index('time', inplace=True)

