"""## ViT - transformers"""

import torch
import torch.nn as nn
import torch.nn.functional as F

# ---------------------------------------------------
# Patch embedding + bloques Transformer
# ---------------------------------------------------

class PatchEmbedding(nn.Module):
    """
    Conv2d que trocea la imagen en patches y los proyecta a un embedding.
    - in_ch: canales de entrada (3 para RGB, L para secuencia temporal, etc.)
    - patch_size: tamaño de patch (p x p)
    - emb_dim: dimensión del embedding
    """
    def __init__(self, in_ch=3, patch_size=16, emb_dim=256):
        super().__init__()
        self.patch_size = patch_size
        self.proj = nn.Conv2d(
            in_ch, emb_dim,
            kernel_size=patch_size,
            stride=patch_size
        )

    def forward(self, x):
        # x: [B, C, H, W]
        x = self.proj(x)                # [B, emb_dim, H_p, W_p]
        B, E, H_p, W_p = x.shape
        x = x.flatten(2).transpose(1, 2)  # [B, N, E]  (N = H_p * W_p)
        return x, H_p, W_p


class TransformerEncoderBlock(nn.Module):
    """
    Bloque estándar de Transformer encoder:
    LN -> MultiheadAttention -> residual
    LN -> MLP -> residual
    """
    def __init__(self, dim, heads=8, mlp_dim=512, dropout=0.1):
        super().__init__()
        self.norm1 = nn.LayerNorm(dim)
        self.attn = nn.MultiheadAttention(
            dim, heads,
            dropout=dropout,
            batch_first=True
        )
        self.norm2 = nn.LayerNorm(dim)
        self.mlp = nn.Sequential(
            nn.Linear(dim, mlp_dim),
            nn.GELU(),
            nn.Dropout(dropout),
            nn.Linear(mlp_dim, dim),
            nn.Dropout(dropout),
        )

    def forward(self, x):
        # x: [B, N, dim]
        h = x
        x = self.norm1(x)
        x, _ = self.attn(x, x, x)  # self-attention
        x = x + h                  # residual 1

        h = x
        x = self.norm2(x)
        x = self.mlp(x)
        x = x + h                  # residual 2
        return x


class ViTSeg2D(nn.Module):
    """
    ViT para segmentación:
    - Embedding de patches
    - Varios bloques Transformer
    - Cabeza lineal por patch
    - Upsample a resolución completa (H, W)

    Devuelve logits [B, out_ch, H, W] compatible con BCE/Dice.
    """
    def __init__(self, in_ch, out_ch=1, base=32,
                 img_size=512, patch_size=16,
                 depth=6, heads=8, mlp_mult=4, dropout=0.1):
        super().__init__()

        self.img_size = img_size
        self.patch_size = patch_size

        # Uso 'base' para escalar la dimensión del embedding (p.ej. 32 -> 256)
        emb_dim = base * 8  # 32 -> 256, 64 -> 512, etc.

        self.patch_embed = PatchEmbedding(
            in_ch=in_ch,
            patch_size=patch_size,
            emb_dim=emb_dim
        )

        # Positional embedding para todos los patches (suponiendo img_size fijo)
        n_patches = (img_size // patch_size) * (img_size // patch_size)
        self.pos_embedding = nn.Parameter(
            torch.zeros(1, n_patches, emb_dim)
        )

        self.dropout = nn.Dropout(dropout)

        mlp_dim = emb_dim * mlp_mult
        self.blocks = nn.ModuleList([
            TransformerEncoderBlock(
                dim=emb_dim,
                heads=heads,
                mlp_dim=mlp_dim,
                dropout=dropout
            )
            for _ in range(depth)
        ])

        self.norm = nn.LayerNorm(emb_dim)
        self.head = nn.Linear(emb_dim, out_ch)  # 1 canal = logits de agua

    def forward(self, x):
        """
        x: [B, C, H, W]
        Devuelve: logits [B, out_ch, H, W]
        """
        B, C, H, W = x.shape

        # Asumimos que ya estás usando resize_to=(512,512)
        assert H == self.img_size and W == self.img_size, \
            f"ViT espera imágenes {self.img_size}x{self.img_size}, recibí {H}x{W}"

        # Embedding de patches
        tokens, H_p, W_p = self.patch_embed(x)  # [B, N, E]
        N = tokens.shape[1]

        assert N == self.pos_embedding.shape[1], \
            f"Número de patches {N} != pos_embedding {self.pos_embedding.shape[1]} (revisa img_size/patch_size)"

        # Agrego posición y paso por los bloques Transformer
        x_tok = tokens + self.pos_embedding      # [B, N, E]
        x_tok = self.dropout(x_tok)

        for blk in self.blocks:
            x_tok = blk(x_tok)

        x_tok = self.norm(x_tok)

        # Cabeza de segmentación: logits por patch
        logits_patch = self.head(x_tok)          # [B, N, out_ch]
        B2, N2, C_out = logits_patch.shape
        assert B2 == B and N2 == N

        # Reorganizo a mapa 2D [B, out_ch, H_p, W_p]
        logits_patch = logits_patch.permute(0, 2, 1).reshape(B, C_out, H_p, W_p)

        # Upsample bilineal a [B, out_ch, H, W]
        logits = F.interpolate(
            logits_patch,
            size=(H, W),
            mode='bilinear',
            align_corners=False
        )
        return logits

# ---------------------------------------------------
# Reemplazos drop-in: mismas firmas que tus U-Nets
# ---------------------------------------------------

class UNetSmall(ViTSeg2D):
    """
    Reemplazo ViT para la U-Net 2D "clásica" que usabas con 3 canales (RGB / bandas ópticas).
    Firma compatible con el código original:
        UNetSmall(in_ch=3, out_ch=1, base=32)
    """
    def __init__(self, in_ch=3, out_ch=1, base=32,
                 img_size=512, patch_size=16,
                 depth=6, heads=8, mlp_mult=4, dropout=0.1):
        super().__init__(
            in_ch=in_ch,
            out_ch=out_ch,
            base=base,
            img_size=img_size,
            patch_size=patch_size,
            depth=depth,
            heads=heads,
            mlp_mult=mlp_mult,
            dropout=dropout
        )


class UNet2D(ViTSeg2D):
    """
    Reemplazo ViT para la U-Net temporal 2D:
    - in_ch = L (cantidad de frames NDWI u otra variable en la ventana temporal)

    Firma compatible con:
        UNet2D(in_ch, base=32)
    que muy probablemente ya uses dentro de train_temporal_cnn.
    """
    def __init__(self, in_ch, base=32,
                 img_size=512, patch_size=16,
                 depth=6, heads=8, mlp_mult=4, dropout=0.1):
        super().__init__(
            in_ch=in_ch,
            out_ch=1,
            base=base,
            img_size=img_size,
            patch_size=patch_size,
            depth=depth,
            heads=heads,
            mlp_mult=mlp_mult,
            dropout=dropout
        )

# ===========================================================
# ENTRENAR ViT (UNetSmall) + PREDECIR + VISUALIZAR RESULTADOS
# ===========================================================
import numpy as np
import torch
from torch.utils.data import DataLoader
import time

device = "cuda" if torch.cuda.is_available() else "cpu"
print("Usando device:", device)

# ---------------------------------------------
# 1) Split train/val con las mismas variables
#    del notebook: a_m_sync, water_sync, times_sel
# ---------------------------------------------

# split 80/20 sobre las fechas seleccionadas
rng = np.random.RandomState(0)
perm = rng.permutation(len(times_sel))
n_val = max(1, int(0.2 * len(times_sel))) if len(times_sel) >= 2 else 0
val_idx = perm[:n_val] if n_val > 0 else np.array([], dtype=int)
tr_idx  = perm[n_val:] if n_val > 0 else perm

times_tr  = [times_sel[i] for i in tr_idx]
times_val = [times_sel[i] for i in val_idx]

print(f"Fechas train: {len(times_tr)}  |  Fechas val: {len(times_val)}")

# stats de normalización (zscore) sólo con train
means, stds = compute_channel_stats_full(a_m_sync, times=times_tr)

# datasets RGB+máscara (usa tu RGBMonthDataset original)
ds_tr  = RGBMonthDataset(
    a_m_sync, water_sync, times_tr,
    resize_to=(512, 512),
    normalize="zscore",
    stats=(means, stds),
    augment=True,
)

ds_val = RGBMonthDataset(
    a_m_sync, water_sync, times_val,
    resize_to=(512, 512),
    normalize="zscore",
    stats=(means, stds),
    augment=False,
) if len(times_val) > 0 else None

# loaders
dl_tr  = DataLoader(ds_tr,  batch_size=2, shuffle=True,  num_workers=0)
dl_val = DataLoader(ds_val, batch_size=2, shuffle=False, num_workers=0) if ds_val is not None else None

print("Batches train:", len(dl_tr), "| Batches val:", len(dl_val) if dl_val is not None else 0)

# ---------------------------------------------
# 2) Definir el modelo ViT (UNetSmall redefinido) y el optimizador
# ---------------------------------------------

# IMPORTANTE: UNetSmall ya fue redefinida como ViTSeg2D en la celda anterior
net = UNetSmall(in_ch=3, out_ch=1, base=32).to(device)
opt = torch.optim.Adam(net.parameters(), lr=1e-3)

# ---------------------------------------------
# 3) Función de una época (usa masked_bce_dice_loss ya definida)
# ---------------------------------------------

def run_epoch(loader, train=True):
    """
    Recorre un DataLoader y devuelve el loss promedio.
    loader devuelve: (img, mask, valid_mask)
    img:  [B,3,H,W]
    mask: [B,1,H,W]
    valid_mask: [B,1,H,W]
    """
    if loader is None or len(loader) == 0:
        return np.nan

    if train:
        net.train()
    else:
        net.eval()

    total = 0.0
    n = 0

    with torch.set_grad_enabled(train):
        for img, msk, vld in loader:
            img = img.to(device)          # [B,3,H,W]
            msk = msk.to(device)          # [B,1,H,W]
            vld = vld.to(device)          # [B,1,H,W]

            logits = net(img)             # [B,1,H,W] (ViT)
            loss = masked_bce_dice_loss(logits, msk, vld)

            if train:
                opt.zero_grad()
                loss.backward()
                opt.step()

            total += float(loss.item())
            n += 1

    return total / max(n, 1)

# ---------------------------------------------
# 4) Loop de entrenamiento
# ---------------------------------------------

EPOCHS = 30          # ajusta según tiempo/datos
best_val = np.inf
best_state = None
history = []

for ep in range(1, EPOCHS + 1):
    t0 = time.time()
    tr_loss = run_epoch(dl_tr, train=True)
    val_loss = run_epoch(dl_val, train=False)
    dt = time.time() - t0

    history.append(
        {
            "epoch": ep,
            "train_loss": tr_loss,
            "val_loss": val_loss,
            "sec": dt,
        }
    )

    val_str = f"{val_loss:.4f}" if not np.isnan(val_loss) else "—"
    print(f"Epoch {ep:02d} | train {tr_loss:.4f} | val {val_str} | {dt:.1f} s")

    if not np.isnan(val_loss) and val_loss < best_val:
        best_val = val_loss
        best_state = {k: v.detach().cpu().clone() for k, v in net.state_dict().items()}

# cargar mejor estado en net
if best_state is not None:
    net.load_state_dict(best_state)
    print("Se cargó el mejor modelo (val_loss = {:.4f})".format(best_val))

# ---------------------------------------------
# 5) Predicción con el modelo ViT sobre TODAS las fechas (student_all)
# ---------------------------------------------

student_all = predict_all_times(
    a_m_sync,
    net,
    (means, stds),
    resize_to=(512, 512),
    thr=0.5,
    device=device,
)

print("student_all:", student_all)

# ---------------------------------------------
# 6) Visualizar algunas clasificaciones (RGB vs máscara ViT)
# ---------------------------------------------

# Por ejemplo, primeras 8 fechas
try:
    _ = plot_rgb_student_pairs(
        a_m_sync,
        student_all.isel(time=slice(0, 12)),
        col_wrap=2,
        title_fmt="%Y-%m",
    )
except Exception as e:
    print("Error al plotear parejas RGB/student:", e)

import gradio as gr
from PIL import Image
import numpy as np
import torch
from torchvision import transforms
import ee
from io import BytesIO
from urllib.request import urlopen

IMG_SIZE = 512
BANDS = ['SR_B5', 'SR_B4', 'SR_B3']  # NIR, RED, GREEN

# ------------------------------------------------------
# 📥 Descargar imagen Landsat con bandas SR_B5, SR_B4, SR_B3
# ------------------------------------------------------
def descargar_landsat_rgb(lon1, lat1, lon2, lat2):
    roi = ee.Geometry.Rectangle([lon1, lat1, lon2, lat2])

    def rename_l5(img):
        return img.select(
            ['SR_B1','SR_B2','SR_B3','SR_B4','SR_B5','SR_B7'],
            ['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7']
        ).copyProperties(img, ['system:time_start'])

    l5 = ee.ImageCollection("LANDSAT/LT05/C02/T1_L2") \
        .filterBounds(roi).filterDate('1984', '2013') \
        .map(rename_l5).map(lambda im: im.clip(roi))

    l8 = ee.ImageCollection("LANDSAT/LC08/C02/T1_L2") \
        .filterBounds(roi).filterDate('2013', '2025') \
        .map(lambda im: im.clip(roi))

    l9 = ee.ImageCollection("LANDSAT/LC09/C02/T1_L2") \
        .filterBounds(roi).filterDate('2021', '2025') \
        .map(lambda im: im.clip(roi))

    all_landsat = l5.merge(l8).merge(l9)
    img = all_landsat.sort('CLOUD_COVER').first().select(BANDS)

    url = img.getThumbURL({
        'region': roi,
        'dimensions': IMG_SIZE,
        'format': 'png',
        'min': 0,
        'max': 30000
    })

    with urlopen(url) as response:
        img_bytes = response.read()
    return Image.open(BytesIO(img_bytes)).convert('RGB')

# ------------------------------------------------------
# 🔍 Inferencia con ViT
# ------------------------------------------------------
def segmentar_area_bbox(coord_str):
    try:
        lon1, lat1, lon2, lat2 = map(float, coord_str.split(','))
        print(f"📍 Coordenadas: {lon1}, {lat1}, {lon2}, {lat2}")

        img_rgb = descargar_landsat_rgb(lon1, lat1, lon2, lat2)
        print("✅ Imagen descargada")

        tf = transforms.Compose([
            transforms.Resize((IMG_SIZE, IMG_SIZE)),
            transforms.ToTensor(),
            transforms.Normalize(mean=means, std=stds)  # 👈 asegurarse que sean los del entrenamiento
        ])
        tensor = tf(img_rgb).unsqueeze(0).to(next(net.parameters()).device)

        with torch.no_grad():
            logits = net(tensor)
            probs = torch.sigmoid(logits)
            mask = (probs > 0.5).float()

        mask_np = mask.squeeze().cpu().numpy()
        mask_img = Image.fromarray((mask_np * 255).astype(np.uint8))

        return img_rgb, mask_img

    except Exception as e:
        print(f"❌ Error durante inferencia: {e}")
        try:
            return img_rgb, Image.new("RGB", (IMG_SIZE, IMG_SIZE), color="red")
        except:
            red_img = Image.new("RGB", (IMG_SIZE, IMG_SIZE), color="red")
            return red_img, red_img

iface = gr.Interface(
    fn=segmentar_area_bbox,
    inputs=gr.Textbox(label="Coordenadas (lon1,lat1,lon2,lat2)", placeholder="-68.226,-24.506,-68.189,-24.539"),
    outputs=[
        gr.Image(type="pil", label="Imagen Landsat (B5-B4-B3)"),
        gr.Image(type="pil", label="Máscara segmentada")
    ],
    title="🌎 Segmentación ViT con Landsat",
    description="Ejemplo de coordenadas: -68.226,-24.506,-68.189,-24.539",
    flagging_mode="never"  # 👈 cambio aquí
)

iface.launch(debug=True)